// 國家安全挑戰賽 2026-27 — 題目出處與原文 (ns-sources.js)
// 資料來源：《國家安全挑戰賽(2627)-法例出處》v3 對應資料（共 354 條），憲法／基本法條文引自官方全文
// 每條: q = 題目, law = 來源法律／文件, ref = 位置, text = 原文引錄或解說
var NS_QUESTION_SOURCES = (typeof window !== "undefined" && window.NS_QUESTION_SOURCES) || {
  "中華人民共和國的一切權力屬於誰？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q2（第2頁） · 見《憲法》第二條","text":"第二條中華人民共和國的一切權力屬於人民。人民行使國家權力的機關是全國人民代表大會和地方各級人民代表大會。人民依照法律規定，通過各種途徑和形式，管理國家事務，管理經濟和文化事業，管理社會事務。"},
  "中華人民共和國的國家機構實行甚麼原則？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q3（第2頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：民主集中制。"},
  "中華人民共和國的根本制度是甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q1（第2頁） · 見《憲法》第一條","text":"第一條中華人民共和國是工人階級領導的、以工農聯盟爲基礎的人民民主專政的社會主義國家。社會主義制度是中華人民共和國的根本制度。中國共產黨領導是中國特色社會主義最本質的特徵。禁止任何組織或者個人破壞社會主義制度。"},
  "中華人民共和國社會主義經濟制度的基礎是甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q5（第2頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：生產資料的社會主義公有制。"},
  "全國性行政區域劃分有哪些？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q17（第3頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：省、自治區、直轄市、特別行政區。"},
  "國家保護和改善生活環境和甚麼環境？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q15（第3頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：生態環境。"},
  "國家建立怎樣的社會保障制度？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q9（第2頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：同經濟發展水平相適應。"},
  "國家推廣全國通用的語言是？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q13（第3頁） · 見《憲法》第十九條","text":"第十九條國家發展社會主義的教育事業，提高全國人民的科學文化水平。國家舉辦各種學校，普及初等義務教育，發展中等教育、職業教育和高等教育，並且發展學前教育。國家發展各種教育設施，掃除文盲，對工人、農民、國家工作人員和其他勞動者進行政治、文化、科學、技術、業務的教育，鼓勵自學成才。國家鼓勵集體經濟組織、國家企業事業組織和其他社會力量依照法律規定舉辦各種教育事業。國家推廣全國通用的普通話。"},
  "國家禁止任何個人破壞甚麼財產？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q8（第2頁） · 見《憲法》第十二條","text":"第十二條社會主義的公共財產神聖不可侵犯。國家保護社會主義的公共財產。禁止任何組織或者個人用任何手段侵佔或者破壞國家的和集體的財產。"},
  "國有企業在法律規定的範圍內有甚麼權利？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q10（第2頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：自主經營。"},
  "在中國境內的外國企業及中外合資企業的合法權益受甚麼法律保護？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q11（第3頁） · 見《憲法》第十八條","text":"第十八條中華人民共和國允許外國的企業和其他經濟組織或者個人依照中華人民共和國法律的規定在中國投資，同中國的企業或者其他經濟組織進行各種形式的經濟合作。在中國境內的外國企業和其他外國經濟組織以及中外合資經營的企業，都必須遵守中華人民共和國的法律。它們的合法的權利和利益受中華人民共和國法律的保護。"},
  "在國家統一領導下，各少數民族聚居的地方實行甚麼制度？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q4（第2頁） · 見《憲法》第四條","text":"第四條中華人民共和國各民族一律平等。國家保障各少數民族的合法的權利和利益，維護和發展各民族的平等團結互助和諧關係。禁止對任何民族的歧視和壓迫，禁止破壞民族團結和製造民族分裂的行爲。國家根據各少數民族的特點和需要，幫助各少數民族地區加速經濟和文化的發展。各少數民族聚居的地方實行區域自治，設立自治機關，行使自治權。各民族自治地方都是中華人民共和國不可分離的部分。各民族都有使用和發展自己的語言文字的自由，都有保持或者改革自己的風俗習慣的自由。"},
  "在我國，國民經濟中的主導力量是？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q14（第3頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：國有經濟。"},
  "城市的土地屬於誰所有？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q7（第2頁） · 見《憲法》第十條","text":"第十條城市的土地屬於國家所有。農村和城市郊區的土地，除由法律規定屬於國家所有的以外，屬於集體所有；宅基地和自留地、自留山，也屬於集體所有。國家爲了公共利益的需要，可以依照法律規定對土地實行徵收或者徵用並給予補償。任何組織或者個人不得侵佔、買賣或者以其他形式非法轉讓土地。土地的使用權可以依照法律的規定轉讓。一切使用土地的組織和個人必須合理地利用土地。"},
  "有權決定設立特別行政區的國家機關是？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q12（第3頁） · 見《憲法》第三十一條、第六十二條","text":"第三十一條國家在必要時得設立特別行政區。在特別行政區內實行的制度按照具體情況由全國人民代表大會以法律規定。"},
  "根據《憲法》第二十八條規定，國家鎮壓甚麼犯罪活動？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q16（第3頁） · 見《憲法》第二十八條","text":"根據《中華人民共和國憲法》及競賽學習參考資料：叛國和其他危害國家安全的犯罪活動。"},
  "農村集體經濟組織實行的雙層經營體制以甚麼為基礎？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q6（第2頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：家庭承包經營。"},
  "《憲法》對男女工資有甚麼規定？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q26（第4頁） · 見《憲法》第四十八條","text":"根據《中華人民共和國憲法》及競賽學習參考資料：男女同工同酬。"},
  "中華人民共和國保護華僑的哪些方面？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q27（第4頁） · 見《憲法》第五十條","text":"第五十條中華人民共和國保護華僑的正當的權利和利益，保護歸僑和僑眷的合法的權利和利益。"},
  "中華人民共和國公民是否有宗教信仰自由？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q20（第3頁） · 見《憲法》第三十六條","text":"第三十六條中華人民共和國公民有宗教信仰自由。任何國家機關、社會團體和個人不得強制公民信仰宗教或者不信仰宗教，不得歧視信仰宗教的公民和不信仰宗教的公民。國家保護正常的宗教活動。任何人不得利用宗教進行破壞社會秩序、損害公民身體健康、妨礙國家教育制度的活動。宗教團體和宗教事務不受外國勢力的支配。"},
  "中華人民共和國公民有沒有義務納稅？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q33（第5頁） · 見《憲法》第五十六條","text":"第五十六條中華人民共和國公民有依照法律納稅的義務。第三章國家機構第一節全國人民代表大會"},
  "中華人民共和國的公民年滿多少周歲有選舉權？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q19（第3頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：年滿十八周歲。"},
  "依照法律服兵役和參加民兵組織是誰的光榮義務？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q32（第5頁） · 見《憲法》第五十五條","text":"第五十五條保衛祖國、抵抗侵略是中華人民共和國每一個公民的神聖職責。依照法律服兵役和參加民兵組織是中華人民共和國公民的光榮義務。"},
  "公安或檢察機關可因甚麼需要檢查通信？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q22（第4頁） · 見《憲法》第四十條","text":"根據《中華人民共和國憲法》及競賽學習參考資料：國家安全或者追查刑事犯罪的需要。"},
  "公民是否不得有危害國家安全、榮譽和利益的行為？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q31（第5頁） · 見《憲法》第五十四條","text":"第五十四條中華人民共和國公民有維護祖國的安全、榮譽和利益的義務，不得有危害祖國的安全、榮譽和利益的行爲。"},
  "公民是否必須遵守憲法和法律？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q30（第5頁） · 見《憲法》第五十三條","text":"第五十三條中華人民共和國公民必須遵守憲法和法律，保守國家祕密，愛護公共財產，遵守勞動紀律，遵守公共秩序，尊重社會公德。"},
  "公民是否有維護國家統一和民族團結的義務？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q29（第5頁） · 見《憲法》第五十二條","text":"第五十二條中華人民共和國公民有維護國家統一和全國各民族團結的義務。"},
  "公民是否都有受教育的權利和義務？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q25（第4頁） · 見《憲法》第四十六條","text":"第四十六條中華人民共和國公民有受教育的權利和義務。國家培養青年、少年、兒童在品德、智力、體質等方面全面發展。"},
  "公民行使自由和權利時，能否損害他人合法權益？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q28（第4頁） · 見《憲法》第五十一條","text":"第五十一條中華人民共和國公民在行使自由和權利的時候，不得損害國家的、社會的、集體的利益和其他公民的合法的自由和權利。"},
  "具有中國公民資格的法定條件是甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q24（第4頁） · 見《憲法》第三十三條","text":"第三十三條凡具有中華人民共和國國籍的人都是中華人民共和國公民。中華人民共和國公民在法律面前一律平等。國家尊重和保障人權。任何公民享有憲法和法律規定的權利，同時必須履行憲法和法律規定的義務。"},
  "國家對就業前的公民進行甚麼必要的訓練？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q23（第4頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：勞動就業訓練。"},
  "對因政治原因要求避難的外國人，可給予甚麼權利？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q18（第3頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：受庇護的權利。"},
  "根據《憲法》第三十八條規定，中華人民共和國公民的甚麼不受侵犯？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q21（第4頁） · 見《憲法》第三十八條","text":"根據《中華人民共和國憲法》及競賽學習參考資料：人格尊嚴。"},
  "《憲法》修改須由多少比例的全國人大代表通過？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q34（第5頁） · 見《憲法》第六十四條","text":"第六十四條憲法的修改，由全國人民代表大會常務委員會或者五分之一以上的全國人民代表大會代表提議，並由全國人民代表大會以全體代表的三分之二以上的多數通過。法律和其他議案由全國人民代表大會以全體代表的過半數通過。"},
  "中央軍事委員會主席須對哪些機構負責？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q39（第6頁） · 見《憲法》第九十四條","text":"第九十四條中央軍事委員會主席對全國人民代表大會和全國人民代表大會常務委員會負責。第五節地方各級人民代表大會和地方各級人民政府"},
  "人大常委會會議由誰召集？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q35（第5頁） · 見《憲法》第六十八條","text":"第六十八條全國人民代表大會常務委員會委員長主持全國人民代表大會常務委員會的工作，召集全國人民代表大會常務委員會會議。副委員長、祕書長協助委員長工作。委員長、副委員長、祕書長組成委員長會議，處理全國人民代表大會常務委員會的重要日常工作。"},
  "國務院常務會議和國務院全體會議由誰召集？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q38（第6頁） · 見《憲法》第八十八條","text":"第八十八條總理領導國務院的工作。副總理、國務委員協助總理工作。總理、副總理、國務委員、祕書長組成國務院常務會議。總理召集和主持國務院常務會議和國務院全體會議。"},
  "國務院常務會議由甚麼人組成？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q37（第5頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：總理、副總理、國務委員、秘書長。"},
  "最高國家權力機關的執行機關是甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q36（第5頁） · 見《憲法》第八十五條","text":"第八十五條中華人民共和國國務院，即中央人民政府，是最高國家權力機關的執行機關，是最高國家行政機關。"},
  "《國旗及國徽(修訂)條例》在哪一天正式刊憲生效？": {"law":"《國旗及國徽（修訂）條例》","ref":"《識法導航》中學版 第六程 · Q147（第19頁）","text":"《國旗及國徽（修訂）條例》於2021年10月8日在香港特別行政區正式刊憲生效。"},
  "「全民國家安全教育日」訂於每年的哪一天？": {"law":"《中華人民共和國國家安全法》","ref":"《識法導航》中學版 第六程 · Q146（第19頁） · 見《國家安全法》第十四條","text":"《中華人民共和國國家安全法》第十四條訂明，每年4月15日為全民國家安全教育日。"},
  "中華人民共和國國徽，中間是五星照耀下的天安門，周圍是甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q40（第6頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：穀穗和齒輪。"},
  "中華人民共和國國歌《義勇軍進行曲》的作曲人是誰？": {"law":"《中華人民共和國國歌法》","ref":"《識法導航》中學版 第六程 · Q148（第19頁）","text":"《義勇軍進行曲》由田漢作詞、聶耳作曲，2004年寫入《憲法》，2017年《國歌法》訂明其為國歌。"},
  "中華人民共和國的國旗是？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q150（第19頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：五星紅旗。"},
  "國旗與其他旗幟同時升掛時，須將國旗置於哪個位置？": {"law":"《中華人民共和國國旗法》","ref":"《識法導航》中學版 第六程 · Q149（第19頁） · 見《國旗法》第十五條","text":"《中華人民共和國國旗法》訂明，升掛國旗時應將國旗置於中心、較高或者突出的位置。"},
  "2022年是香港回歸祖國多少周年？": {"law":"歷史事實","ref":"《識法導航》中學版 第六程 · Q60（第8頁）","text":"1997年7月1日香港回歸祖國，2022年為回歸25周年。"},
  "《基本法》哪一年起在香港施行？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q42（第6頁）","text":"《基本法》於1990年4月4日通過，自1997年7月1日香港特別行政區成立起施行。"},
  "《基本法》在哪一屆全國人大通過？": {"law":"歷史事實","ref":"《識法導航》中學版 第六程 · Q43（第6頁）","text":"《基本法》於1990年4月4日由第七屆全國人民代表大會第三次會議通過。"},
  "《基本法》規定香港特區法院有甚麼權力？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q49（第7頁） · 見《基本法》第十九條","text":"第十九條香港特別行政區享有獨立的司法權和終審權。香港特別行政區法院除繼續保持香港原有法律制度和原則對法院審判權所作的限制外，對香港特別行政區所有的案件均有審判權。香港特別行政區法院對國防、外交等國家行為無管轄權。香港特別行政區法院在審理案件中遇有涉及國防、外交等國家行為的事實問題，應取得行政長官就該等問題發出的證明文件，上述文件對法院有約束力。行政長官在發出證明文件前，須取得中央人民政府的證明書。"},
  "《基本法》訂明資本主義制度和生活方式多少年不變？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q51（第7頁） · 見《基本法》第五條","text":"第五條香港特別行政區不實行社會主義制度和政策，保持原有的資本主義制度和&#8203;生活方式，五十年不變。"},
  "《基本法》通過哪份法律文件公布？": {"law":"歷史事實","ref":"《識法導航》中學版 第六程 · Q41（第6頁）","text":"《基本法》於1990年4月4日由中華人民共和國主席令第二十六號公布施行。"},
  "《基本法》附件三的全國性法律可通過甚麼方式在香港特別行政區實施？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q59（第8頁） · 見《基本法》第十八條","text":"第十八條所規定的適用於香港特別行政區的法律審判案件，其他普通法適用地區的司法判例可作參考。&#8203;"},
  "中央各部門在港設立機構，須徵得哪個機構同意並經誰批准？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q64（第8頁） · 見《基本法》第二十二條","text":"第二十二條中央人民政府所屬各部門、各省、自治區、直轄市均不得干預香港特別行政區根據本法自行管理的事務。中央各部門、各省、自治區、直轄市如需在香港特別行政區設立機構，須徵得香港特別行政區政府同意並經中央人民政府批准。中央各部門、各省、自治區、直轄市在香港特別行政區設立的一切機構及其人員均須遵守香港特別行政區的法律。中國其他地區的人進入香港特別行政區須辦理批准手續，其中進入香港特別行政區定居的人數由中央人民政府主管部門徵求香港特別行政區政府的意見後確定。香港特別行政區可在北京設立辦事機構。"},
  "哪個機構可向香港特區授予其他權力？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q62（第8頁） · 見《基本法》第二十條","text":"第二十條香港特別行政區可享有全國人民代表大會和全國人民代表大會常務委員會及中央人民政府授予的其他權力。"},
  "哪個機構授權香港自行處理對外事務？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q55（第7頁） · 見《基本法》第十三條","text":"第十三條中央人民政府負責管理與香港特別行政區有關的外交事務。中華人民共和國外交部在香港設立機構處理外交事務。中央人民政府授權香港特別行政區依照本法自行處理有關的對外事務。"},
  "哪個機構有權任命特區行政機關主要官員？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q57（第8頁） · 見《基本法》第十五條","text":"第十五條中央人民政府依照本法第四章的規定任命香港特別行政區行政長官和行政機關的主要官員。"},
  "國家根據哪份法律文件設立香港特別行政區？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q45（第6頁） · 見《憲法》第三十一條","text":"第三十一條國家在必要時得設立特別行政區。在特別行政區內實行的制度按照具體情況由全國人民代表大會以法律規定。"},
  "根據《基本法》第二十三條，特區應自行立法禁止甚麼？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q65（第8頁） · 見《基本法》第二十三條","text":"第二十三條香港特別行政區應自行立法禁止任何叛國、分裂國家、煽動叛亂、顛覆中央人民政府及竊取國家機密的行為，禁止外國的政治性組織或團體在香港特別行政區進行政治活動，禁止香港特別行政區的政治性組織或團體與外國的政治性組織或團體建立聯繫。&#8203;第三章居民的基本權利和義務"},
  "海關關長可否擁有外國居留權？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q50（第7頁） · 見《基本法》第六十一條","text":"第六十一條香港特別行政區的主要官員由在香港通常居住連續滿十五年並在外國無居留權的香港特別行政區永久性居民中的中國公民擔任。"},
  "誰提出「一國兩制」構思？": {"law":"歷史事實","ref":"《識法導航》中學版 第六程 · Q44（第6頁）","text":"「一國兩制」構思由鄧小平提出，為香港回歸奠定基礎。"},
  "香港回歸前原有的法律是否繼續保留？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q52（第7頁） · 見《基本法》第一百六十條","text":"第一百六十條香港特別行政區成立時，香港原有法律除由全國人民代表大會常務委員會宣布為同本法牴觸者外，採用為香港特別行政區法律，如以後發現有的法律與本法牴觸，可依照本法規定的程序修改或停止生效。在香港原有法律下有效的文件、證件、契約和權利義務，在不牴觸本法的前提下繼續有效，受香港特別行政區的承認和保護。&#8203;.mw-parser-output.template-mincho{font-family:\"AppleLiSung\",STSong,\"NotoSerifTC\",\"NotoSerifSC\",PMingLiU,SimSun,\"I.Ming\",\"LXGWNeoZhiSong\",serif}.mw-parser-output.template-mincho:lang(zh-hans),.mw-parser-output.template-mincho:lang(zh-CN),.mw-parser-output.template-mincho:lang(zh-SG){font-family:STSong,\"NotoSerifSC\",SimSun,\"LXGWNeoZhiSong\",serif}.mw-parser-output.template-mincho:lang(zh-hant){font-family:\"AppleLiSung\",\"NotoSerifTC\",PMingLiU,\"I.Ming\",serif}.mw-parser-output.template-mincho:lang(zh-tw){font-family:\"AppleLiSung\",\"NotoSerifTC\",PMingLiU,TW-Sung,MOESongUN,\"I.Ming\",serif}.mw-parser-output.template-mincho:lang(zh-hk){font-family:\"AppleLiSung\",\"NotoSerifHK\",\"NotoSerifTC\",PMingLiU,MingLiU_HKSCS,\"ChironSungHK\",\"ChironSungHKVF\",\"ChironSungHKWS\",\"I.Ming\",serif}.mw-parser-output.template-mincho:lang(zh-mo){font-family:\"AppleLiSung\",\"NotoSerifHK\",\"NotoSerifTC\",PMingLiU,MingLiU_MSCS,MingLiU_HKSCS,\"ChironSungHK\",\"ChironSungHKVF\",\"ChironSungHKWS\",\"I.Ming\",serif}附件一香港特別行政區行政長官的產生辦法一、行政長官由一個具有廣泛代表性的選舉委員會根據本法選出，由中央人民政府任命。二、選舉委員會委員共800人，由下列各界人士組成：工商、金融界200人專業界200人勞工、社會服務、宗教等界200人立法會議員、區域性組織代表、香港地區全國人大代表、香港地區全國政協委員的代表200人選舉委員會每屆任期五年。三、各個界別的劃分，以及每個界別中何種組織可以產生選舉委員的名額，由香港特別行政區根據民主、開放的原則制定選舉法加以規定。各界別法定團體根據選舉法規定的分配名額和選舉辦法自行選出選舉委員會委員。選舉委員以個人身份投票。四、不少於一百名的選舉委員可聯合提名行政長官候選人。每名委員只可提出一名候選人。五、選舉委員會根據提名的名單，經一人一票無記名投票選出行政長官候任人。具體選舉辦法由選舉法規定。六、第一任行政長官按照《全國人民代表大會關於香港特別行政區第一屆政府和立法會產生辦法的決定》產生。七、二〇〇七年以後各任行政長官的產生辦法如需修改，須經立法會全體議員三分之二多數通過，行政長官同意，並報全國人民代表大會常務委員會批准。&#8203;附件二香港特別行政區立法會的產生辦法和表決程序一、立法會的產生辦法（一）香港特別行政區立法會議員每屆60人，第一屆立法會按照《全國人民代表大會關於香港特別行政區第一屆政府和立法會產生辦法的決定》產生。第二屆、第三屆立法會的組成如下：第二屆功能團體選舉的議員30人選舉委員會選舉的議員6人分區直接選舉的議員24人第三屆功能團體選舉的議員30人分區直接選舉的議員30人（二）除第一屆立法會外，上述選舉委員會即本法附件一規定的選舉委員會。上述分區直接選舉的選區劃分、投票辦法，各個功能界別和法定團體的劃分、議員名額的分配、選舉辦法及選舉委員會選舉議員的辦法，由香港特別行政區政府提出並經立法會通過的選舉法加以規定。二、立法會對法案、議案的表決程序除本法另有規定外，香港特別行政區立法會對法案和議案的表決採取下列程序：政府提出的法案，如獲得出席會議的全體議員的過半數票，即為通過。立法會議員個人提出的議案、法案和對政府法案的修正案均須分別經功能團體選舉產生的議員和分區直接選舉、選舉委員會選舉產生的議員兩部分出席會議議員各過半數通過。三、二〇〇七年以後立法會的產生辦法和表決程序&#8203;二〇〇七年以後香港特別行政區立法會的產生辦法和法案、議案的表決程序，如需對本附件的規定進行修改，須經立法會全體議員三分之二多數通過，行政長官同意，並報全國人民代表大會常務委員會備案。附件三在香港特別行政區實施的全國性法律下列全國性法律，自一九九七年七月一日起由香港特別行政區在當地公布或立法實施。一、《關於中華人民共和國國都、紀年、國歌、國旗的決議》二、《關於中華人民共和國國慶日的決議》三、《中央人民政府公布中華人民共和國國徽的命令》附：國徽圖案、說明、使用辦法四、《中華人民共和國政府關於領海的聲明》五、《中華人民共和國國籍法》六、《中華人民共和國外交特權與豁免條例》&#8203;香港特別行政區區旗、區徽圖案香港特別行政區區旗圖案香港特別行政區區徽圖案.mw-parser-output.licenseContainer{box-sizing:border-box;margin-top:1em;margin-bottom:0.25em;clear:both;width:auto;page-break-before:always;break-before:page}.mw-parser-output.licenseContainer>div:first-of-type{display:table;border:2pxsolidvar(--border-subtle,#8888aa);border-collapse:collapse;border-spacing:00;empty-cells:hide;box-sizing:border-box;margin:0auto0auto;width:100%;background-color:var(--background-color-neutral-subtle,#f7f8ff);color:var(--color-base,#202122)}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child{display:table-row-group}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child{display:table-row}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div{display:table-cell;padding:5px;vertical-align:middle;width:auto}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:first-child{text-align:left}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2){text-align:center}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div{width:100%}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div:first-child{display:block;margin:0auto0auto;text-align:left}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div:nth-child(2){display:table;border-top:1pxsolidvar(--border-subtle,#8888aa)}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div:nth-child(2)>div{display:table-cell;vertical-align:middle}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div:nth-child(2)>div:first-child{text-align:center;padding:5px0;width:40px}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(2)>div:nth-child(2)>div:nth-child(2){text-align:left;padding:5px;font-size:92%}.mw-parser-output.licenseContainer>div:first-of-type>div:first-child>div:first-child>div:nth-child(3){text-align:right}.mw-parser-output.licensetpl{display:none}.mw-parser-output.licenseContainer.wst-collapsible-box{clear:both;margin:0.25em00.25em0;font-size:95%;background-color:var(--background-color-neutral-subtle,#f7f8ff);color:var(--color-base,#202122);border:2pxsolidvar(--border-subtle,#8888aa);text-align:left;line-height:1.6}.mw-parser-output.wst-license-container-title{display:inline-block;padding:0.5em}.mw-parser-output.wst-license-container-content{background:transparent;color:inherit;margin:0;padding:3px;text-align:left}.mw-parser-output.licenseContainer.warningLicenseContainer>div:first-child{border:2pxsolidvar(--border-color-error,#b22222);background-color:var(--background-color-error-subtle,#ffeeee);color:var(--color-base,#202122)}.mw-parser-output.licenseContainer.warningLicenseContainer>div:first-child>div:first-child>div:first-child>div:nth-child(2)>div:nth-child(2){border:2pxsolidvar(--border-color-error,#b22222);color:var(--color-base,#202122)}本作品是由全國人民代表大會制定和修改、全國人民代表大會常務委員會部分補充和修改的中華人民共和國基本法律。依據《中華人民共和國著作權法》"},
  "香港在秦代屬於中國版圖的哪一個縣？": {"law":"歷史事實","ref":"《識法導航》中學版 第六程 · Q46（第6頁）","text":"秦代香港地區隸屬南海郡番禺縣。"},
  "香港特別行政區擁有甚麼權力？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q48（第7頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：行政管理權、立法權、獨立的司法權和終審權。"},
  "香港特區哪些制度以《基本法》規定為依據？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q53（第7頁） · 見《基本法》第五條、第六條及第一百零四條等","text":"《基本法》第五條、第六條訂明香港特區的社會、經濟制度及居民權利保障；行政管理、立法和司法制度亦依《基本法》規定。"},
  "香港特區是哪個國家不可分離的部分？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q47（第7頁） · 見《基本法》第一條","text":"第一條香港特別行政區是中華人民共和國不可分離的部分。"},
  "香港特區的甚麼人可參加最高國家權力機關的工作？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q63（第8頁） · 見《基本法》第二十一條","text":"第二十一條香港特別行政區居民中的中國公民依法參與國家事務的管理。根據全國人民代表大會確定的名額和代表產生辦法，由香港特別行政區居民中的中國公民在香港選出香港特別行政區的全國人民代表大會代表，參加最高國家權力機關的工作。"},
  "香港特區直轄於哪個機關？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q54（第7頁） · 見《基本法》第十二條","text":"第十二條香港特別行政區是中華人民共和國的一個享有高度自治權的地方行政區域，直轄於中央人民政府。"},
  "香港發生嚴重災害時，特區政府可如何尋求協助？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q56（第8頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：向中央人民政府請求駐軍協助。"},
  "香港立法機關制定的法律被人大常委會發回後，如何處理？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q58（第8頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：立即失效。"},
  "《公民權利和政治權利國際公約》在香港特別行政區如何實施？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q70（第9頁） · 見《基本法》第三十九條","text":"第三十九條《公民權利和政治權利國際公約》、《經濟、社會與文化權利的國際公約》和國際勞工公約適用於香港的有關規定繼續有效，通過香港特別行政區的法律予以實施。香港居民享有的權利和自由，除依法規定外不得限制，此種限制不得與本條第一款規定牴觸。"},
  "哪一種原居民的合法傳統權益受香港特別行政區的保護？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q71（第9頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：新界原居民。"},
  "哪一類香港特別行政區居民在香港享有選舉權和被選舉權？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q67（第9頁） · 見《基本法》第二十六條","text":"第二十六條香港特別行政區永久性居民依法享有選舉權和被選舉權。"},
  "回歸前已取得的專業執業資格可否保留？": {"law":"過渡安排","ref":"《識法導航》中學版 第六程 · Q114（第15頁）","text":"根據特區成立時的過渡安排，回歸前已取得的專業執業資格予以保留。"},
  "在港的外國旅客可否參加區議會、立法會選舉？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q72（第9頁） · 見《基本法》第二十六條","text":"第二十六條香港特別行政區永久性居民依法享有選舉權和被選舉權。"},
  "有關機構可因為甚麼需要而依照法律程序對通訊進行檢查？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q68（第9頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：公共安全和追查刑事犯罪的需要。"},
  "未參加但已適用於香港的國際協議可否繼續適用？": {"law":"全國人大常委會1997年決定","ref":"《識法導航》中學版 第六程 · Q116（第15頁）","text":"全國人民代表大會常務委員會1997年的決定訂明，中國未參加但已適用於香港的國際協議仍可繼續適用。"},
  "根據《基本法》，勞工的甚麼權利受法律保護？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q69（第9頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：福利待遇和退休保障。"},
  "香港特區居民包括哪兩類？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q66（第9頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：永久性居民和非永久性居民。"},
  "《基本法》對行政長官的年齡要求是多少歲？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q73（第10頁） · 見《基本法》第四十四條","text":"第四十四條香港特別行政區行政長官由年滿四十周歲，在香港通常居住連續滿二十年並在外國無居留權的香港特別行政區永久性居民中的中國公民擔任。"},
  "區議會是否政權性組織？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q103（第13頁） · 見《基本法》第九十七條","text":"第九十七條香港特別行政區可設立非政權性的區域組織，接受香港特別行政區政府就有關地區管理和其他事務的諮詢，或負責提供文化、康樂、環境衛生等服務。"},
  "如要修改香港特別行政區行政長官的產生辦法要經哪一個機構批准？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q74（第10頁） · 見《基本法》附件一","text":"根據《基本法》附件一，行政長官產生辦法如需修改，須經全國人民代表大會常務委員會批准。"},
  "根據《基本法》附件二，政府法案須獲出席議員多少票同意？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q87（第11頁） · 見《基本法》附件二","text":"根據《基本法》附件二，立法會對政府提出的法案的表決，須獲出席會議的議員過半數票同意。"},
  "法官以外的司法人員任免制度能否保持？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q100（第13頁） · 見《基本法》第九十三條","text":"第九十三條香港特別行政區成立前在香港任職的法官和其他司法人員均可留用，其年資予以保留，薪金、津貼、福利待遇和服務條件不低於原來的標準。對退休或符合規定離職的法官和其他司法人員，包括香港特別行政區成立前已退休或離職者，不論其所屬國籍或居住地點，香港特別行政區政府按不低於原來的標準，向&#8203;他們或其家屬支付應得的退休金、酬金、津貼和福利費。"},
  "特區政府可否聘請外籍人士擔任主要官員？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q104（第13頁） · 見《基本法》第六十一條","text":"第六十一條香港特別行政區的主要官員由在香港通常居住連續滿十五年並在外國無居留權的香港特別行政區永久性居民中的中國公民擔任。"},
  "立法會主席如何產生？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q89（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：由立法會議員互選。"},
  "立法會被解散而未能批准預算案撥款時，行政長官在選出新立法會前可怎麼辦？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q80（第11頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：按上一財政年度的開支標準，批准臨時短期撥款。"},
  "立法會議員出任公務人員後，立法會主席該怎麼辦？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q95（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：宣告其喪失立法會議員的資格。"},
  "立法會議員在甚麼時候不受逮捕？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q94（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：出席會議時和赴會途中。"},
  "立法會議員提出涉及政府政策的法律草案前，須得到誰的書面同意？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q92（第12頁） · 見《基本法》第七十四條","text":"第七十四條香港特別行政區立法會議員根據本法規定並依照法定程序提出法律草案，凡不涉及公共開支或政治體制或政府運作者，可由立法會議員個別或聯名提出。凡涉及政府政策者，在提出前必須得到行政長官的書面同意。"},
  "行政長官依法免除終審法院法官的職務，須徵得哪一個機構的同意？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q99（第13頁） · 見《基本法》第九十條","text":"第九十條香港特別行政區終審法院和高等法院的首席法官，應由在外國無居留權的香港特別行政區永久性居民中的中國公民擔任。除本法"},
  "行政長官因立法會拒絕通過財政預算案而解散立法會，重選後原案仍被拒絕，他必須做甚麼？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q81（第11頁） · 見《基本法》第五十二條","text":"第五十二條香港特別行政區行政長官如有下列情況之一者必須辭職：（一）因嚴重疾病或其他原因無力履行職務；（二）因兩次拒絕簽署立法會通過的法案而解散立法會，重選的立法會仍以全體議員三分之二多數通過所爭議的原案，而行政長官仍拒絕簽署；（三）因立法會拒絕通過財政預算案或其他重要法案而解散立法會，重選的立法會繼續拒絕通過所爭議的原案。"},
  "行政長官在甚麼情況下須徵詢行政會議的意見？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q84（第11頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：作出重要決策、向立法會提交法案、制定附屬法規和解散立法會前。"},
  "行政長官就任時向誰申報財產？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q76（第10頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：香港特別行政區終審法院首席法官。"},
  "行政長官短期不能履職時，最先由誰代理？": {"law":"政府架構","ref":"《識法導航》中學版 第六程 · Q82（第11頁）","text":"行政長官短期不能履職時，依次由政務司司長、財政司司長、律政司司長代理。"},
  "行政長官認為立法會通過的法案不符合整體利益，該怎麼辦？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q78（第10頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：在三個月內將法案發回立法會重議。"},
  "行政長官選舉委員會每屆任期多久？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q75（第10頁） · 見《基本法》附件一","text":"根據《基本法》附件一，選舉委員會每屆任期五年。"},
  "誰可以任免香港特別行政區行政會議成員？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q83（第11頁） · 見《基本法》第五十五條","text":"第五十五條香港特別行政區行政會議的成員由行政長官從行政機關的主要官員、立法會議員和社會人士中委任，其任免由行政長官決定。行政會議成員的任期應不超過委任他的行政長官的任期。香港特別行政區行政會議成員由在外國無居留權的香港特別行政區永久性居民中的中國公民擔任。行政長官認為必要時可邀請有關人士列席會議。"},
  "誰可要求立法會主席召開緊急會議？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q90（第12頁） · 見《基本法》第七十二條","text":"第七十二條香港特別行政區立法會主席行使下列職權：&#8203;（一）主持會議；（二）決定議程，政府提出的議案須優先列入議程；（三）決定開會時間；（四）在休會期間可召開特別會議；（五）應行政長官的要求召開緊急會議；（六）立法會議事規則所規定的其他職權。"},
  "誰擁有簽署立法會法案及公布法律的職權？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q77（第10頁） · 見《基本法》第四十八條","text":"第四十八條香港特別行政區行政長官行使下列職權：（一）領導香港特別行政區政府；（二）負責執行本法和依照本法適用於香港特別行政區的其他法律；（三）簽署立法會通過的法案，公布法律；簽署立法會通過的財政預算案，將財政預算、決算報中央人民政府備案；（四）決定政府政策和發布行政命令；（五）提名並報請中央人民政府任命下列主要官員：各司司長、副司長，各局局長，廉政專員，審計署署長，警務處處長，入境事務處處長，海關關長；建議中央人民政府免除上述官員職務；（六）依照法定程序任免各級法院法官；&#8203;（七）依照法定程序任免公職人員；（八）執行中央人民政府就本法規定的有關事務發出的指令；（九）代表香港特別行政區政府處理中央授權的對外事務和其他事務；（十）批准向立法會提出有關財政收入或支出的動議；（十一）根據安全和重大公共利益的考慮，決定政府官員或其他負責政府公務的人員是否向立法會或其屬下的委員會作證和提供證據；（十二）赦免或減輕刑事罪犯的刑罰；（十三）處理請願、申訴事項。"},
  "香港特別行政區律政司主管甚麼工作？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q85（第11頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：刑事檢察工作。"},
  "香港特別行政區政府該如何對立法會負責？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q86（第11頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：執行立法會通過並已生效的法律 定期向立法會作施政報告 答覆立法會議員的質詢徵稅和公共開支須經立法會批准。"},
  "香港特別行政區立法會有__________法律的職權。": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q91（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：制定、修改和廢除。"},
  "香港特別行政區立法會通過的法案，經甚麼程序方可生效？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q93（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：行政長官簽署、公布。"},
  "香港特別行政區終審法院首席法官可否被免職？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q98（第13頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：香港特別行政區法院的法官只有在無力履行職責或行為不檢的情況下，行政長官才可根據終審法院首席法官任命的不少於三名當地法官組成的審議庭的建議，予以免職。"},
  "香港特別行政區行政長官在解散立法會前，必須徵詢哪一個機構的意見？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q79（第10頁） · 見《基本法》第五十六條","text":"第五十六條香港特別行政區行政會議由行政長官主持。行政長官在作出重要決策、向立法會提交法案、制定附屬法規和解散立法會前，須徵詢行政會議的意見，但人事任免、紀律制裁和緊急情況下採取的措施除外。行政長官如不採納行政會議多數成員的意見，應將具體理由記錄在案。"},
  "香港特區如何與全國其他地區的司法機關聯繫和相互協助？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q101（第13頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：通過協商。"},
  "香港特區如何與外國就司法互助作出安排？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q102（第13頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：在中央人民政府協助或授權下。"},
  "香港特區法院的法官由誰任命？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q97（第13頁） · 見《基本法》第八十八條","text":"第八十八條香港特別行政區法院的法官，根據當地法官和法律界及其他方面知名人士組成的獨立委員會推薦，由行政長官任命。"},
  "香港特區首屆立法會任期多久？": {"law":"全國人民代表大會決定","ref":"《識法導航》中學版 第六程 · Q88（第12頁）","text":"根據全國人民代表大會的決定，首屆立法會任期兩年。"},
  "高等法院設立甚麼法庭？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q96（第12頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：上訴法庭和原訟法庭。"},
  "《基本法》修改議案列入人大議程前，先由誰研究？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q121（第15頁） · 見《基本法》第一百五十九條","text":"第一百五十九條本法的修改權屬於全國人民代表大會。本法的修改提案權屬於全國人民代表大會常務委員會，國務院和香港特別行政區。香港特別行政區的修改議案，須經香港特別行政區的全國人民代表大會代表三分之二多數、香港特別行政區立法會全體議員三分之二多數和香港特別行政區行政長官同意後，交由香港特別行政區出席全國人民代表大會的代表團向全國人民代表大會提出。本法的修改議案在列入全國人民代表大會的議程前，先由香港特別行政區基本法委員會研究並提出意見。本法的任何修改，均不得同中華人民共和國對香港既定的基本方針政策相牴觸。第九章附則"},
  "《基本法》是否保障香港私人企業主的合法財產？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q115（第15頁） · 見《基本法》第六條","text":"根據《識法導航》中學版（第六程），本題所考內容見該課程對應章節。"},
  "人大常委會授權香港法院對《基本法》哪些條款自行解釋？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q119（第15頁） · 見《基本法》第一百五十八條","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：香港特別行政區自治範圍內的條款。"},
  "人大常委會解釋《基本法》前，須徵詢哪個機關的意見？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q120（第15頁） · 見《基本法》第一百五十八條","text":"第一百五十八條本法的解釋權屬於全國人民代表大會常務委員會。全國人民代表大會常務委員會授權香港特別行政區法院在審理案件時對本法關於香港特別行政區自治範圍內的條款自行解釋。香港特別行政區法院在審理案件時對本法的其他條款也可解釋。但如香港特別行政&#8203;區法院在審理案件時需要對本法關於中央人民政府管理的事務或中央和香港特別行政區關係的條款進行解釋，而該條款的解釋又影響到案件的判決，在對該案件作出不可上訴的終局判決前，應由香港特別行政區終審法院請全國人民代表大會常務委員會對有關條款作出解釋。如全國人民代表大會常務委員會作出解釋，香港特別行政區法院在引用該條款時，應以全國人民代表大會常務委員會的解釋為準。但在此以前作出的判決不受影響。全國人民代表大會常務委員會在對本法進行解釋前，徵詢其所屬的香港特別行政區基本法委員會的意見。"},
  "外國在港設立官方機構，須經誰批准？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q118（第15頁） · 見《基本法》第十三條","text":"中央人民政府負責管理與香港特別行政區有關的外交事務，外國在港設立官方機構須經中央人民政府批准。"},
  "滿期而沒有續期權利的土地契約如何處理？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q110（第14頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：由香港特別行政區自行制定法律和政策處理。"},
  "甚麼航空器進入香港特別行政區前，須經中央人民政府特別許可？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q112（第14頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：外國國家航空器。"},
  "甚麼船隻進入香港特別行政區須經中央人民政府特別許可？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q111（第14頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：外國軍用船隻。"},
  "行政長官就職時除宣誓擁護《基本法》外，還須效忠甚麼？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q105（第14頁） · 見《基本法》第一百零四條","text":"第一百零四條香港特別行政區行政長官、主要官員、行政會議成員、立法會議員、各級法院法官和其他司法人員在就職時必須依法宣誓擁護中華人民共和國香港特別行政區基本法，效忠中華人民共和國香港特別行政區。第五章經濟第一節財政、金融、貿易和工商業"},
  "香港在外國設立官方經濟機構，須報誰備案？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q117（第15頁） · 見《基本法》第十三條","text":"中央人民政府負責管理與香港特別行政區有關的外交事務，香港在外國設立官方經濟機構須報中央人民政府備案。"},
  "香港特別行政區財政預算以甚麼為原則？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q107（第14頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：量入為出。"},
  "香港特區以甚麼名義參加國際組織和貿易協定？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q109（第14頁） · 見《基本法》第一百五十二條","text":"第一百五十二條對以國家為單位參加的、同香港特別行政區有關的、適當領域的國際組織和國際會議，香港特別行政區政府可派遣代表作為中華人民共和國代表團的成員或以中央人民政府和上述有關國際組織或國際會議允許的身份參加，並以「中國香港」的名義發表意見。香港特別行政區可以「中國香港」的名義參加不以國家為單位參加的國際組織和國際會議。對中華人民共和國已參加而香港也以某種形式參加了的國際組織，中央人民政府將採取必要措施使香港特別行政區以適當形式繼續保持在這些組織中的地位。對中華人民共和國尚未參加而香港已以某種形式參加的國際組織，中央人民政府將根據需要使香港特別行政區以適當形式繼續參加這些組織。"},
  "香港特區宗教組織可繼續興辦甚麼？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q113（第15頁）","text":"根據《中華人民共和國香港特別行政區基本法》及競賽學習參考資料：宗教院校、其他學校、醫院和福利機構。"},
  "香港特區是否實行外匯管制？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q108（第14頁） · 見《基本法》第一百一十二條","text":"第一百一十二條香港特別行政區不實行外匯管制政策。港幣自由兌換。繼續開放外匯、黃金、證券、期貨等市場。香港特別行政區政府保障資金的流動和進出自由。"},
  "香港特區的財政收入須上繳中央嗎？": {"law":"《中華人民共和國香港特別行政區基本法》","ref":"《識法導航》中學版 第六程 · Q106（第14頁） · 見《基本法》第一百零六條","text":"第一百零六條香港特別行政區保持財政獨立。香港特別行政區的財政收入全部用於自身需要，不上繳中央人民政府。中央人民政府不在香港特別行政區徵稅。"},
  "《國安法》尊重香港特區獨立的司法權、終審權及甚麼？": {"law":"《中華人民共和國憲法》","ref":"《識法導航》中學版 第六程 · Q137（第18頁）","text":"根據《中華人民共和國憲法》及競賽學習參考資料：核心價值。"},
  "《基本法》哪兩條是根本性條款？": {"law":"學習參考資料","ref":"第一章 總則 · 第二條","text":"關於香港特別行政區法律地位的香港特別行政區基本法第一條和第十二條規定是香港特別行政區基本法的根本性條款。香港特別行政區任何機構、組織和個人行使權利和自由,不得違背香港特別行政區基本法第一條和第十二條的規定。"},
  "《港區國安法》保護根據哪兩份國際公約享有的權利和自由？": {"law":"學習參考資料","ref":"第一章 總則 · 第四條","text":"依法保護香港特別行政區居民根據香港特別行政區基本法和《公民權利和政治權利國際公約》、《經濟、社會與文化權利的國際公約》適用於香港的有關規定享有的包括言論、新聞、出版的自由,結社、集會、遊行、示威的自由在內的權利和自由。"},
  "《港區國安法》共分為多少章？": {"law":"學習參考資料","ref":"目錄","text":"第一章 總則；第二章 香港特別行政區維護國家安全的職責和機構；第三章 罪行和處罰；第四章 案件管轄、法律適用和程序；第五章 中央人民政府駐香港特別行政區維護國家安全機構；第六章 附則"},
  "《港區國安法》列入《基本法》附件三是根據哪一條？": {"law":"學習參考資料","ref":"公布文件 · 鑑於段","text":"鑑於《中華人民共和國香港特別行政區基本法》第十八條規定,列於該法附件三的全國性法律,由香港特別行政區在當地公布或立法實施,並規定全國人民代表大會常務委員會在徵詢其所屬的香港特別行政區基本法委員會和香港特別行政區政府的意見後,可對列於該法附件三的法律作出增減。"},
  "《港區國安法》制定的法律依據是什麼？": {"law":"學習參考資料","ref":"第一章 總則 · 第一條","text":"根據中華人民共和國憲法、中華人民共和國香港特別行政區基本法和全國人民代表大會關於建立健全香港特別行政區維護國家安全的法律制度和執行機制的決定,制定本法。"},
  "《港區國安法》於何時通過？": {"law":"學習參考資料","ref":"附表標題","text":"《中華人民共和國香港特別行政區維護國家安全法》(2020年6月30日第十三屆全國人民代表大會常務委員會第二十次會議通過)"},
  "《港區國安法》旨在堅定不移並全面準確貫徹什麼方針？": {"law":"學習參考資料","ref":"第一章 總則 · 第一條","text":"為堅定不移並全面準確貫徹“一國兩制”、“港人治港”、高度自治的方針,維護國家安全……制定本法。"},
  "《港區國安法》是在哪次會議上通過的？": {"law":"學習參考資料","ref":"附表標題","text":"《中華人民共和國香港特別行政區維護國家安全法》(2020年6月30日第十三屆全國人民代表大會常務委員會第二十次會議通過)"},
  "《港區國安法》由誰公布在香港特別行政區實施？": {"law":"學習參考資料","ref":"公布文件","text":"因此本人,香港特別行政區行政長官林鄭月娥,現公布:列於附表的《中華人民共和國香港特別行政區維護國家安全法》自2020年6月30日晚上11時起在香港特別行政區實施。"},
  "《港區國安法》第一章總則之下有哪幾章？": {"law":"學習參考資料","ref":"目錄","text":"第二章 香港特別行政區維護國家安全的職責和機構；第三章 罪行和處罰；第四章 案件管轄、法律適用和程序；第五章 中央人民政府駐香港特別行政區維護國家安全機構；第六章 附則"},
  "《港區國安法》自何時起在香港特別行政區實施？": {"law":"學習參考資料","ref":"公布文件","text":"因此本人,香港特別行政區行政長官林鄭月娥,現公布:列於附表的《中華人民共和國香港特別行政區維護國家安全法》自2020年6月30日晚上11時起在香港特別行政區實施。"},
  "《港區國安法》規定維護國家安全應當尊重和保障什麼？": {"law":"學習參考資料","ref":"第一章 總則 · 第四條","text":"香港特別行政區維護國家安全應當尊重和保障人權,依法保護香港特別行政區居民根據香港特別行政區基本法和《公民權利和政治權利國際公約》、《經濟、社會與文化權利的國際公約》適用於香港的有關規定享有的包括言論、新聞、出版的自由,結社、集會、遊行、示威的自由在內的權利和自由。"},
  "《港區國安法》防範、制止和懲治的四類犯罪是什麼？": {"law":"學習參考資料","ref":"第一章 總則 · 第一條","text":"防範、制止和懲治與香港特別行政區有關的分裂國家、顛覆國家政權、組織實施恐怖活動和勾結外國或者境外勢力危害國家安全等犯罪,保持香港特別行政區的繁榮和穩定,保障香港特別行政區居民的合法權益。"},
  "中央人民政府對香港特區有關的國家安全事務負有什麼責任？": {"law":"學習參考資料","ref":"第一章 總則 · 第三條第一款","text":"中央人民政府對香港特別行政區有關的國家安全事務負有根本責任。"},
  "中央人民政府提出要求時，行政長官應當怎樣？": {"law":"學習參考資料","ref":"第一章 總則 · 第十一條第二款","text":"如中央人民政府提出要求,行政長官應當就維護國家安全特定事項及時提交報告。"},
  "人大常委會徵詢誰的意見後，可對《基本法》附件三法律作出增減？": {"law":"學習參考資料","ref":"公布文件 · 鑑於段","text":"鑑於《中華人民共和國香港特別行政區基本法》第十八條規定,列於該法附件三的全國性法律,由香港特別行政區在當地公布或立法實施,並規定全國人民代表大會常務委員會在徵詢其所屬的香港特別行政區基本法委員會和香港特別行政區政府的意見後,可對列於該法附件三的法律作出增減。"},
  "任何人未經司法機關判罪之前均如何假定？": {"law":"學習參考資料","ref":"第一章 總則 · 第五條第二款","text":"任何人未經司法機關判罪之前均假定無罪。保障犯罪嫌疑人、被告人和其他訴訟參與人依法享有的辯護權和其他訴訟權利。"},
  "哪一個機關對香港特別行政區有關的國家安全事務負有根本責任？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q125（第16頁） · 第一章 總則 · 第三條第一款","text":"中央人民政府對香港特別行政區有關的國家安全事務負有根本責任。"},
  "在港的任何機構、組織和個人可從事危害國家安全的行為嗎？": {"law":"學習參考資料","ref":"第一章 總則 · 第六條第二款","text":"在香港特別行政區的任何機構、組織和個人都應當遵守本法和香港特別行政區有關維護國家安全的其他法律,不得從事危害國家安全的行為和活動。"},
  "經司法程序最終定罪或宣告無罪後，可否就同一行為再審？": {"law":"學習參考資料","ref":"第一章 總則 · 第五條第二款","text":"任何人已經司法程序被最終確定有罪或者宣告無罪的,不得就同一行為再予審判或者懲罰。"},
  "維護國家主權、統一和領土完整是誰的義務？": {"law":"學習參考資料","ref":"第一章 總則 · 第六條第一款","text":"維護國家主權、統一和領土完整是包括香港同胞在內的全中國人民的共同義務。"},
  "行政長官須就履行維護國家安全職責的情況提交什麼報告？": {"law":"學習參考資料","ref":"第一章 總則 · 第十一條第一款","text":"香港特別行政區行政長官應當就香港特別行政區維護國家安全事務向中央人民政府負責,並就香港特別行政區履行維護國家安全職責的情況提交年度報告。"},
  "防範、制止和懲治危害國家安全犯罪，應當堅持什麼原則？": {"law":"學習參考資料","ref":"第一章 總則 · 第五條第一款","text":"防範、制止和懲治危害國家安全犯罪,應當堅持法治原則。法律規定為犯罪行為的,依照法律定罪處刑;法律沒有規定為犯罪行為的,不得定罪處刑。"},
  "香港居民在參選或就任公職時應當怎樣？": {"law":"學習參考資料","ref":"第一章 總則 · 第六條第三款","text":"香港特別行政區居民在參選或者就任公職時應當依法簽署文件確認或者宣誓擁護中華人民共和國香港特別行政區基本法,效忠中華人民共和國香港特別行政區。"},
  "香港特別行政區居民參加區議會、立法會選舉時須簽署確認甚麼？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q134（第17頁） · 第一章 總則 · 第六條第三款","text":"香港特別行政區居民在參選或者就任公職時應當依法簽署文件確認或者宣誓擁護中華人民共和國香港特別行政區基本法,效忠中華人民共和國香港特別行政區。"},
  "香港特區何時開始負有維護國安的憲制責任？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q127（第16頁） · 第一章 總則 · 第三條第二款","text":"香港特別行政區負有維護國家安全的憲制責任,應當履行維護國家安全的職責。（自1997年7月1日回歸日起）"},
  "香港特區哪些機關須依法防範、制止和懲治危害國家安全的行為？": {"law":"學習參考資料","ref":"第一章 總則 · 第三條第三款","text":"香港特別行政區行政機關、立法機關、司法機關應當依據本法和其他有關法律規定有效防範、制止和懲治危害國家安全的行為和活動。"},
  "香港特區應當通過哪些途徑開展國家安全教育？": {"law":"學習參考資料","ref":"第一章 總則 · 第十條","text":"香港特別行政區應當通過學校、社會團體、媒體、網絡等開展國家安全教育,提高香港特別行政區居民的國家安全意識和守法意識。"},
  "香港特區行政長官應就維護國家安全事務向誰負責？": {"law":"學習參考資料","ref":"第一章 總則 · 第十一條第一款","text":"香港特別行政區行政長官應當就香港特別行政區維護國家安全事務向中央人民政府負責,並就香港特別行政區履行維護國家安全職責的情況提交年度報告。"},
  "香港特區負有維護國家安全的什麼責任？": {"law":"學習參考資料","ref":"第一章 總則 · 第三條第二款","text":"香港特別行政區負有維護國家安全的憲制責任,應當履行維護國家安全的職責。"},
  "中央國家安全委員會的主席是誰？": {"law":"事實","ref":"《識法導航》中學版 第六程 · Q124（第16頁）","text":"中央國家安全委員會由習近平擔任主席。"},
  "任命警務處國安部門負責人前，須書面徵求哪個機構？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十六條第二款","text":"警務處維護國家安全部門負責人由行政長官任命,行政長官任命前須書面徵求本法第四十八條規定的機構(中央人民政府駐香港特別行政區維護國家安全公署)的意見。"},
  "哪一個政府部門負責危害國家安全犯罪案件的檢控工作？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q128（第17頁） · 第二章第二節 機構 · 第十八條第一款","text":"香港特別行政區律政司設立專門的國家安全犯罪案件檢控部門,負責危害國家安全犯罪案件的檢控工作和其他相關法律事務。"},
  "國安委秘書處由誰領導？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十三條第二款","text":"香港特別行政區維護國家安全委員會下設秘書處,由秘書長領導。"},
  "國安委秘書長如何產生？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十三條第二款","text":"秘書長由行政長官提名,報中央人民政府任命。"},
  "國安委設立什麼顧問？由誰指派？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十五條","text":"香港特別行政區維護國家安全委員會設立國家安全事務顧問,由中央人民政府指派,就香港特別行政區維護國家安全委員會履行職責相關事務提供意見。"},
  "國家安全事務顧問在國安委會議中擔當什麼角色？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十五條","text":"國家安全事務顧問列席香港特別行政區維護國家安全委員會會議。"},
  "律政司國安案件檢控部門的檢控官由誰任命？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十八條第一款","text":"該部門檢控官由律政司長徵得香港特別行政區維護國家安全委員會同意後任命。"},
  "律政司設立什麼部門，負責危害國家安全犯罪案件的檢控工作？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十八條第一款","text":"香港特別行政區律政司設立專門的國家安全犯罪案件檢控部門,負責危害國家安全犯罪案件的檢控工作和其他相關法律事務。"},
  "維護國家安全委員會下設什麼機構？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十三條第二款","text":"香港特別行政區維護國家安全委員會下設秘書處,由秘書長領導。秘書長由行政長官提名,報中央人民政府任命。"},
  "維護國家安全委員會作出的決定可以司法覆核嗎？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十四條第二款","text":"香港特別行政區維護國家安全委員會的工作不受香港特別行政區任何其他機構、組織和個人的干涉,工作信息不予公開。香港特別行政區維護國家安全委員會作出的決定不受司法覆核。"},
  "維護國家安全委員會接受誰的監督和問責？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十二條","text":"香港特別行政區設立維護國家安全委員會,負責香港特別行政區維護國家安全事務,承擔維護國家安全的主要責任,並接受中央人民政府的監督和問責。"},
  "維護國家安全委員會的工作信息可以公開嗎？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十四條第二款","text":"香港特別行政區維護國家安全委員會的工作不受香港特別行政區任何其他機構、組織和個人的干涉,工作信息不予公開。"},
  "維護國家安全的專門款項從哪裡撥出？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十九條","text":"經行政長官批准,香港特別行政區政府財政司長應當從政府一般收入中撥出專門款項支付關於維護國家安全的開支並核准所涉及的人員編制,不受香港特別行政區現行有關法律規定的限制。"},
  "誰應當從政府一般收入中撥出專門款項支付維護國家安全的開支？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十九條","text":"經行政長官批准,香港特別行政區政府財政司長應當從政府一般收入中撥出專門款項支付關於維護國家安全的開支並核准所涉及的人員編制,不受香港特別行政區現行有關法律規定的限制。"},
  "警務處國安部門可從哪裡聘請專門人員和技術人員？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十六條第三款","text":"警務處維護國家安全部門可以從香港特別行政區以外聘請合格的專門人員和技術人員,協助執行維護國家安全相關任務。"},
  "警務處國安部門的職責是什麼？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十七條","text":"(一)收集分析涉及國家安全的情報信息;(二)部署、協調、推進維護國家安全的措施和行動;(三)調查危害國家安全犯罪案件;(四)進行反干預調查和開展國家安全審查;(五)承辦香港特別行政區維護國家安全委員會交辦的維護國家安全工作;(六)執行本法所需的其他職責。"},
  "警務處國安部門負責人就職時須宣誓做什麼？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十六條第二款","text":"警務處維護國家安全部門負責人在就職時應當宣誓擁護中華人民共和國香港特別行政區基本法,效忠中華人民共和國香港特別行政區,遵守法律,保守秘密。"},
  "警務處維護國家安全部門負責人及律政司國家安全犯罪案件檢控部門負責人由誰任命？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q131（第17頁） · 第二章第二節 機構 · 第十六條第二款、第十八條第二款","text":"警務處維護國家安全部門負責人由行政長官任命……律政司國家安全犯罪案件檢控部門負責人由行政長官任命……"},
  "財政司長須就維護國家安全專門款項向誰提交報告？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十九條第二款","text":"財政司長須每年就該款項的控制和管理向立法會提交報告。"},
  "香港特別行政區維護國家安全委員會的秘書長由誰任命？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q132（第17頁） · 第二章第二節 機構 · 第十三條第二款","text":"秘書長由行政長官提名,報中央人民政府任命。"},
  "香港特別行政區警務處設立維護國家安全的部門負責甚麼工作？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q130（第17頁） · 第二章第二節 機構 · 第十七條","text":"警務處維護國家安全部門的職責為:(一)收集分析涉及國家安全的情報信息;……"},
  "香港特區政府警務處設立什麼部門？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十六條第一款","text":"香港特別行政區政府警務處設立維護國家安全的部門,配備執法力量。"},
  "香港特區維護國家安全委員會承擔維護國家安全的什麼責任？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十二條","text":"香港特別行政區設立維護國家安全委員會,負責香港特別行政區維護國家安全事務,承擔維護國家安全的主要責任,並接受中央人民政府的監督和問責。"},
  "香港特區維護國家安全委員會由誰擔任主席？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十三條第一款","text":"香港特別行政區維護國家安全委員會由行政長官擔任主席,成員包括政務司長、財政司長、律政司長、保安局局長、警務處處長、本法第十六條規定的警務處維護國家安全部門的負責人、入境事務處處長、海關關長和行政長官辦公室主任。"},
  "香港特區維護國家安全委員會的成員包括哪些？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十三條第一款","text":"成員包括政務司長、財政司長、律政司長、保安局局長、警務處處長、本法第十六條規定的警務處維護國家安全部門的負責人、入境事務處處長、海關關長和行政長官辦公室主任。"},
  "香港特區維護國家安全委員會的職責是什麼？": {"law":"學習參考資料","ref":"第二章第二節 機構 · 第十四條第一款","text":"(一)分析研判香港特別行政區維護國家安全形勢,規劃有關工作,制定香港特別行政區維護國家安全政策;(二)推進香港特別行政區維護國家安全的法律制度和執行機制建設;(三)協調香港特別行政區維護國家安全的重點工作和重大行動。"},
  "香港特區設立什麼機構負責維護國家安全事務？": {"law":"學習參考資料","ref":"第二章第一節 職責 · 第二章第二節 機構 · 第十二條","text":"香港特別行政區設立維護國家安全委員會,負責香港特別行政區維護國家安全事務,承擔維護國家安全的主要責任,並接受中央人民政府的監督和問責。"},
  "《港區國安法》指明的恐怖活動包括哪些？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十四條第一款","text":"(一)針對人的嚴重暴力;(二)爆炸、縱火或者投放毒害性、放射性、傳染病病原體等物質;(三)破壞交通工具、交通設施、電力設備、燃氣設備或者其他易燃易爆設備;(四)嚴重干擾、破壞水、電、燃氣、交通、通訊、網絡等公共服務和管理的電子控制系統;(五)以其他危險方法嚴重危害公眾健康或者安全。"},
  "《港區國安法》適用於施行以前的行為嗎？": {"law":"學習參考資料","ref":"第三章第六節 效力範圍 · 第三十九條","text":"本法施行以後的行為,適用本法定罪處刑。"},
  "《香港國安法》懲處的四大罪行是甚麼？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q123（第16頁） · 第三章 罪行和處罰 · 目錄","text":"第一節 分裂國家罪；第二節 顛覆國家政權罪；第三節 恐怖活動罪；第四節 勾結外國或者境外勢力危害國家安全罪"},
  "任何人經法院判決犯危害國家安全罪行後，喪失什麼資格？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十五條第一款","text":"任何人經法院判決犯危害國家安全罪行的,即喪失作為候選人參加香港特別行政區舉行的立法會、區議會選舉或者出任香港特別行政區任何公職或者行政長官選舉委員會委員的資格。"},
  "公司、團體等法人或者非法人組織實施本法規定的犯罪的，如何處罰？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十一條","text":"公司、團體等法人或者非法人組織實施本法規定的犯罪的,對該組織判處罰金。公司、團體等法人或者非法人組織因犯本法規定的罪行受到刑事處罰的,應責令其暫停運作或者吊銷其執照或者營業許可證。"},
  "分裂國家罪的犯罪行為包括哪些？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十條第一款","text":"任何人組織、策劃、實施或者參與實施以下旨在分裂國家、破壞國家統一行為之一的,不論是否使用武力或者以武力相威脅,即屬犯罪:(一)將香港特別行政區或者中華人民共和國其他任何部分從中華人民共和國分離出去;(二)非法改變香港特別行政區或者中華人民共和國其他任何部分的法律地位;(三)將香港特別行政區或者中華人民共和國其他任何部分轉歸外國統治。"},
  "勾結外國或者境外勢力危害國家安全罪的行為包括哪些？": {"law":"學習參考資料","ref":"第三章第四節 勾結外國或者境外勢力危害國家安全罪 · 第二十九條第一款","text":"(一)對中華人民共和國發動戰爭,或者以武力或者武力相威脅,對中華人民共和國主權、統一和領土完整造成嚴重危害;(二)對香港特別行政區政府或者中央人民政府制定和執行法律、政策進行嚴重阻撓並可能造成嚴重後果;(三)對香港特別行政區選舉進行操控、破壞並可能造成嚴重後果;(四)對香港特別行政區或者中華人民共和國進行制裁、封鎖或者採取其他敵對行動;(五)通過各種非法方式引發香港特別行政區居民對中央人民政府或者香港特別行政區政府的憎恨並可能造成嚴重後果。"},
  "哪些情形可以對犯罪行為人從輕、減輕處罰，犯罪較輕的可以免除處罰？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十三條第一款","text":"(一)在犯罪過程中,自動放棄犯罪或者自動有效地防止犯罪結果發生的;(二)自動投案,如實供述自己的罪行的;(三)揭發他人犯罪行為,查證屬實,或者提供重要線索得以偵破其他案件的。"},
  "哪些情況下會被認為是在香港特別行政區內犯罪？": {"law":"學習參考資料","ref":"第三章第六節 效力範圍 · 第三十六條","text":"任何人在香港特別行政區內實施本法規定的犯罪的,適用本法。犯罪的行為或者結果有一項發生在香港特別行政區內的,就認為是在香港特別行政區內犯罪。在香港特別行政區註冊的船舶或者航空器內實施本法規定的犯罪的,也適用本法。"},
  "因實施本法規定的犯罪而獲得的違法所得以及用於犯罪的資金和工具，應當如何處理？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十二條","text":"因實施本法規定的犯罪而獲得的資助、收益、報酬等違法所得以及用於或者意圖用於犯罪的資金和工具,應當予以追繳、沒收。"},
  "在境外針對香港實施《香港國安法》列明的罪行，適用本法嗎？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q136（第18頁） · 第三章第六節 效力範圍 · 第三十七條、第三十八條","text":"香港特別行政區永久性居民……在香港特別行政區以外實施本法規定的犯罪的,適用本法……不具有香港特別行政區永久性居民身份的人在香港特別行政區以外針對香港特別行政區實施本法規定的犯罪的,適用本法。"},
  "宣揚恐怖主義、煽動實施恐怖活動的，情節嚴重的如何處罰？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十七條","text":"宣揚恐怖主義、煽動實施恐怖活動的,即屬犯罪。情節嚴重的,處五年以上十年以下有期徒刑,並處罰金或者沒收財產;其他情形,處五年以下有期徒刑、拘役或者管制,並處罰金。"},
  "恐怖活動罪是為了脅迫誰或威嚇公眾以圖實現政治主張的犯罪？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十四條","text":"為脅迫中央人民政府、香港特別行政區政府或者國際組織或者威嚇公眾以圖實現政治主張,組織、策劃、實施、參與實施或者威脅實施以下造成或者意圖造成嚴重社會危害的恐怖活動之一的,即屬犯罪。"},
  "為外國或境外機構竊取、刺探、收買、非法提供國家秘密或情報，屬於什麼罪行？": {"law":"學習參考資料","ref":"第三章第四節 勾結外國或者境外勢力危害國家安全罪 · 第二十九條第一款","text":"為外國或者境外機構、組織、人員竊取、刺探、收買、非法提供涉及國家安全的國家秘密或者情報的……均屬犯罪。"},
  "為恐怖活動提供培訓、武器、資金、場所等支持，情節嚴重的如何處罰？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十六條第一款","text":"為恐怖活動組織、恐怖活動人員、恐怖活動實施提供培訓、武器、信息、資金、物資、勞務、運輸、技術或者場所等支持、協助、便利……情節嚴重的,處五年以上十年以下有期徒刑,並處罰金或者沒收財產;其他情形,處五年以下有期徒刑、拘役或者管制,並處罰金。"},
  "煽動、協助、教唆或資助他人分裂國家，情節嚴重的如何處罰？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十一條","text":"任何人煽動、協助、教唆、以金錢或者其他財物資助他人實施本法第二十條規定的犯罪的,即屬犯罪。情節嚴重的,處五年以上十年以下有期徒刑;情節較輕的,處五年以下有期徒刑、拘役或者管制。"},
  "犯分裂國家罪，不論是否使用武力或者以武力相威脅，即屬犯罪嗎？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十條第一款","text":"任何人組織、策劃、實施或者參與實施以下旨在分裂國家、破壞國家統一行為之一的,不論是否使用武力或者以武力相威脅,即屬犯罪。"},
  "犯分裂國家罪，對其他參加的處什麼刑罰？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十條第二款","text":"對其他參加的,處三年以下有期徒刑、拘役或者管制。"},
  "犯分裂國家罪，對積極參加的處什麼刑罰？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十條第二款","text":"對積極參加的,處三年以上十年以下有期徒刑;對其他參加的,處三年以下有期徒刑、拘役或者管制。"},
  "犯分裂國家罪，對首要分子或者罪行重大的處什麼刑罰？": {"law":"學習參考資料","ref":"第三章第一節 分裂國家罪 · 第二十條第二款","text":"犯前款罪,對首要分子或者罪行重大的,處無期徒刑或者十年以上有期徒刑;對積極參加的,處三年以上十年以下有期徒刑;對其他參加的,處三年以下有期徒刑、拘役或者管制。"},
  "犯勾結外國或者境外勢力危害國家安全罪的如何處罰？": {"law":"學習參考資料","ref":"第三章第四節 勾結外國或者境外勢力危害國家安全罪 · 第二十九條第二款","text":"犯前款罪,處三年以上十年以下有期徒刑;罪行重大的,處無期徒刑或者十年以上有期徒刑。"},
  "積極參加恐怖活動組織的如何處罰？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十五條第一款","text":"積極參加的,處三年以上十年以下有期徒刑,並處罰金;其他參加的,處三年以下有期徒刑、拘役或者管制,可以並處罰金。"},
  "立法會議員、政府官員等公職人員經判決犯危害國家安全罪行後，其職務如何？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十五條第一款","text":"曾經宣誓或者聲明擁護中華人民共和國香港特別行政區基本法、效忠中華人民共和國香港特別行政區的立法會議員、政府官員及公務人員、行政會議成員、法官及其他司法人員、區議員,即時喪失該等職務,並喪失參選或者出任上述職務的資格。"},
  "組織、領導恐怖活動組織的如何處罰？": {"law":"學習參考資料","ref":"第三章第三節 恐怖活動罪 · 第二十五條第一款","text":"組織、領導恐怖活動組織的,即屬犯罪,處無期徒刑或者十年以上有期徒刑,並處沒收財產;積極參加的,處三年以上十年以下有期徒刑,並處罰金;其他參加的,處三年以下有期徒刑、拘役或者管制,可以並處罰金。"},
  "非永久性居民在境外針對香港犯本法罪行，適用本法嗎？": {"law":"學習參考資料","ref":"第三章第六節 效力範圍 · 第三十八條","text":"不具有香港特別行政區永久性居民身份的人在香港特別行政區以外針對香港特別行政區實施本法規定的犯罪的,適用本法。"},
  "非香港永久性居民犯本法罪行，可適用什麼處罰？": {"law":"學習參考資料","ref":"第三章第五節 其他處罰規定 · 第三十四條第一款","text":"不具有香港特別行政區永久性居民身份的人實施本法規定的犯罪的,可以獨立適用或者附加適用驅逐出境。"},
  "顛覆國家政權罪的犯罪行為包括哪些？": {"law":"學習參考資料","ref":"第三章第二節 顛覆國家政權罪 · 第二十二條第一款","text":"任何人組織、策劃、實施或者參與實施以下以武力、威脅使用武力或者其他非法手段旨在顛覆國家政權行為之一的,即屬犯罪:(一)推翻、破壞中華人民共和國憲法所確立的中華人民共和國根本制度;(二)推翻中華人民共和國中央政權機關或者香港特別行政區政權機關;(三)嚴重干擾、阻撓、破壞中華人民共和國中央政權機關或者香港特別行政區政權機關依法履行職能;(四)攻擊、破壞香港特別行政區政權機關履職場所及其設施,致使其無法正常履行職能。"},
  "香港永久性居民或本地公司在境外犯本法罪行，適用本法嗎？": {"law":"學習參考資料","ref":"第三章第六節 效力範圍 · 第三十七條","text":"香港特別行政區永久性居民或者在香港特別行政區成立的公司、團體等法人或者非法人組織在香港特別行政區以外實施本法規定的犯罪的,適用本法。"},
  "不宜公開審理的案件，判決結果應當如何？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十一條第四款","text":"禁止新聞界和公眾旁聽全部或者一部分審理程序,但判決結果應當一律公開宣佈。"},
  "危害國家安全罪犯案件可在甚麼法院審理？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q135（第17頁） · 第四章 案件管轄、法律適用和程序 · 第四十四條第三款","text":"在裁判法院、區域法院、高等法院和終審法院就危害國家安全犯罪案件提起的刑事檢控程序應當分別由各該法院的指定法官處理。"},
  "哪些人不得被指定為審理國安案件的法官？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十四條第二款","text":"凡有危害國家安全言行的,不得被指定為審理危害國家安全犯罪案件的法官。"},
  "審判應當公開進行，什麼情況下可禁止新聞界和公眾旁聽全部或一部分審理程序？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十一條第四款","text":"審判應當公開進行。因為涉及國家秘密、公共秩序等情形不宜公開審理的,禁止新聞界和公眾旁聽全部或者一部分審理程序,但判決結果應當一律公開宣佈。"},
  "審理危害國家安全犯罪案件的指定法官由誰指定？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十四條第一款","text":"香港特別行政區行政長官應當從裁判官、區域法院法官、高等法院原訟法庭法官、上訴法庭法官以及終審法院法官中指定若干名法官,也可從暫委或者特委法官中指定若干名法官,負責處理危害國家安全犯罪案件。"},
  "對犯罪嫌疑人、被告人，什麼情況下不得准予保釋？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十二條第二款","text":"對犯罪嫌疑人、被告人,除非法官有充足理由相信其不會繼續實施危害國家安全行為的,不得准予保釋。"},
  "對警務處國安部門的調查措施，哪個機構負有監督責任？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十三條第二款","text":"香港特別行政區維護國家安全委員會對警務處維護國家安全部門等執法機構採取本條第一款規定措施負有監督責任。"},
  "律政司長可基於什麼理由指示案件毋須陪審團審理？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十六條第一款","text":"律政司長可基於保護國家秘密、案件具有涉外因素或者保障陪審員及其家人的人身安全等理由,發出證書指示相關訴訟毋須在有陪審團的情況下進行審理。"},
  "律政司長發出證書後，高等法院原訟法庭應當如何審理？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十六條第一款","text":"凡律政司長發出上述證書,高等法院原訟法庭應當在沒有陪審團的情況下進行審理,並由三名法官組成審判庭。"},
  "指定法官任期多久？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十四條第一款","text":"上述指定法官任期一年。"},
  "指定法官可以從哪些法官中指定？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十四條第一款","text":"從裁判官、區域法院法官、高等法院原訟法庭法官、上訴法庭法官以及終審法院法官中指定若干名法官,也可從暫委或者特委法官中指定若干名法官。"},
  "指定法官在獲任期間如有危害國家安全言行，會怎樣？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十四條第二款","text":"在獲任指定法官期間,如有危害國家安全言行的,終止其指定法官資格。"},
  "未經律政司長書面同意不得檢控的規定，影響逮捕犯罪嫌疑人並將其羈押嗎？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十一條第二款","text":"但該規定不影響就有關犯罪依法逮捕犯罪嫌疑人並將其羈押,也不影響該等犯罪嫌疑人申請保釋。"},
  "未經誰的書面同意，任何人不得就危害國家安全犯罪案件提出檢控？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十一條第二款","text":"未經律政司長書面同意,任何人不得就危害國家安全犯罪案件提出檢控。"},
  "法院審理案件中遇有涉及國家秘密的認定問題，應取得誰發出的證明書？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十七條","text":"香港特別行政區法院在審理案件中遇有涉及有關行為是否涉及國家安全或者有關證據材料是否涉及國家秘密的認定問題,應取得行政長官就該等問題發出的證明書,上述證明書對法院有約束力。"},
  "警務處國安部門辦案時可採取哪些特別措施？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十三條第一款","text":"(一)搜查可能存有犯罪證據的處所、車輛、船隻、航空器以及其他有關地方和電子設備;(二)要求涉嫌實施危害國家安全犯罪行為的人員交出旅行證件或者限制其離境;(三)對與犯罪相關的財產,予以凍結,申請限制令、押記令、沒收令以及充公;(四)要求信息發佈人或者有關服務商移除信息或者提供協助;(五)要求外國及境外政治性組織,外國及境外當局或者政治性組織的代理人提供資料;(六)經行政長官批准,對有合理理由懷疑涉及實施危害國家安全犯罪的人員進行截取通訊和秘密監察;(七)對有合理理由懷疑擁有與偵查有關的資料或者管有有關物料的人員,要求其回答問題和提交資料或者物料。"},
  "香港法院審理甚麼案件須取得行政長官證明文件？": {"law":"《港區國安法》","ref":"《識法導航》中學版 第六程 · Q61（第8頁） · 見《港區國安法》第四十七條","text":"根據《港區國安法》第四十七條，法院審理案件中遇有涉及國防、外交等國家行為的事實問題認定，應取得行政長官證明文件。"},
  "香港特區對本法規定的犯罪案件行使管轄權，但本法哪條規定的情形除外？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十條","text":"香港特別行政區對本法規定的犯罪案件行使管轄權,但本法第五十五條規定的情形除外。"},
  "香港特區管轄的危害國家安全犯罪案件的審判循什麼程序進行？": {"law":"學習參考資料","ref":"第四章 案件管轄、法律適用和程序 · 第四十一條第三款","text":"香港特別行政區管轄的危害國家安全犯罪案件的審判循公訴程序進行。"},
  "中央人民政府在香港設立什麼機構？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第四十八條第一款","text":"中央人民政府在香港特別行政區設立維護國家安全公署。中央人民政府駐香港特別行政區維護國家安全公署依法履行維護國家安全職責,行使相關權力。"},
  "哪些情況下，駐港國安公署對危害國家安全犯罪案件行使管轄權？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十五條","text":"(一)案件涉及外國或者境外勢力介入的複雜情況,香港特別行政區管轄確有困難的;(二)出現香港特別行政區政府無法有效執行本法的嚴重情況的;(三)出現國家安全面臨重大現實威脅的情況的。"},
  "持駐港國安公署證件的人員車輛執行職務時，可被港方檢查扣押嗎？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第六十條第二款","text":"持有駐香港特別行政區維護國家安全公署制發的證件或者證明文件的人員和車輛等在執行職務時不受香港特別行政區執法人員檢查、搜查和扣押。"},
  "駐港國安公署人員由誰派出？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第四十八條第二款","text":"駐香港特別行政區維護國家安全公署人員由中央人民政府維護國家安全的有關機關聯合派出。"},
  "駐港國安公署及其人員依據本法執行職務的行為，受香港特別行政區管轄嗎？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第六十條第一款","text":"駐香港特別行政區維護國家安全公署及其人員依據本法執行職務的行為,不受香港特別行政區管轄。"},
  "駐港國安公署履行職責時，特區政府須如何配合？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第六十一條","text":"駐香港特別行政區維護國家安全公署依據本法規定履行職責時,香港特別行政區政府有關部門須提供必要的便利和配合,對妨礙有關執行職務的行為依法予以制止並追究責任。"},
  "駐港國安公署應當加強與哪些機構的工作聯繫和工作協同？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十二條","text":"駐香港特別行政區維護國家安全公署應當加強與中央人民政府駐香港特別行政區聯絡辦公室、外交部駐香港特別行政區特派員公署、中國人民解放軍駐香港部隊的工作聯繫和工作協同。"},
  "駐港國安公署根據第五十五條管轄案件時，由誰負責立案偵查？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十六條","text":"由駐香港特別行政區維護國家安全公署負責立案偵查,最高人民檢察院指定有關檢察機關行使檢察權,最高人民法院指定有關法院行使審判權。"},
  "駐港國安公署的經費由誰保障？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十一條","text":"駐香港特別行政區維護國家安全公署的經費由中央財政保障。"},
  "駐港國安公署的職責是什麼？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第四十九條","text":"(一)分析研判香港特別行政區維護國家安全形勢,就維護國家安全重大戰略和重要政策提出意見和建議;(二)監督、指導、協調、支持香港特別行政區履行維護國家安全的職責;(三)收集分析國家安全情報信息;(四)依法辦理危害國家安全犯罪案件。"},
  "駐港國安公署管轄案件時，犯罪嫌疑人自何時起有權委託律師作為辯護人？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十八條第一款","text":"犯罪嫌疑人自被駐香港特別行政區維護國家安全公署第一次訊問或者採取強制措施之日起,有權委託律師作為辯護人。"},
  "駐港國安公署管轄案件時，由誰行使檢察權和審判權？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十六條","text":"最高人民檢察院指定有關檢察機關行使檢察權,最高人民法院指定有關法院行使審判權。"},
  "駐港國安公署管轄案件的訴訟程序事宜，適用什麼法律？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十七條第一款","text":"根據本法第五十五條規定管轄案件的立案偵查、審查起訴、審判和刑罰的執行等訴訟程序事宜,適用《中華人民共和國刑事訴訟法》等相關法律的規定。"},
  "駐港國安公署與哪個機構建立協調機制？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十三條第一款","text":"駐香港特別行政區維護國家安全公署應當與香港特別行政區維護國家安全委員會建立協調機制,監督、指導香港特別行政區維護國家安全工作。"},
  "駐港國安公署與外交部駐港特派員公署加強管理哪些機構？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十四條","text":"駐香港特別行政區維護國家安全公署、外交部駐香港特別行政區特派員公署會同香港特別行政區政府採取必要措施,加強對外國和國際組織駐香港特別行政區機構、在香港特別行政區的外國和境外非政府組織和新聞機構的管理和服務。"},
  "駐港國安公署行使管轄權須經過什麼程序？": {"law":"學習參考資料","ref":"第五章 中央人民政府駐香港特別行政區維護國家安全機構 · 第五十五條","text":"有以下情形之一的,經香港特別行政區政府或者駐香港特別行政區維護國家安全公署提出,並報中央人民政府批准,由駐香港特別行政區維護國家安全公署對本法規定的危害國家安全犯罪案件行使管轄權。"},
  "《港區國安法》的解釋權屬於誰？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十五條","text":"本法的解釋權屬於全國人民代表大會常務委員會。"},
  "《港區國安法》自何時起施行？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十六條","text":"本法自公佈之日起施行。"},
  "擔任辯護人或者訴訟代理人的律師，應當保守什麼秘密？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十三條第二款","text":"擔任辯護人或者訴訟代理人的律師應當保守在執業活動中知悉的國家秘密、商業秘密和個人隱私。"},
  "本法「拘役」在香港參照適用什麼？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十四條","text":"“拘役”參照適用香港特別行政區相關法律規定的“監禁”“入勞役中心”“入教導所”"},
  "本法「有期徒刑」「無期徒刑」在香港分別指什麼？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十四條","text":"本法規定的“有期徒刑”“無期徒刑”“沒收財產”和“罰金”分別指“監禁”“終身監禁”“充公犯罪所得”和“罰款”"},
  "本法「沒收財產」「罰金」在香港分別指什麼？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十四條","text":"本法規定的“有期徒刑”“無期徒刑”“沒收財產”和“罰金”分別指“監禁”“終身監禁”“充公犯罪所得”和“罰款”"},
  "本法「管制」在香港參照適用什麼？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十四條","text":"“管制”參照適用香港特別行政區相關法律規定的“社會服務令”“入感化院”"},
  "辦案執法司法機關對辦案中知悉的哪些事項須保密？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十三條第一款","text":"辦理本法規定的危害國家安全犯罪案件的有關執法、司法機關及其人員……應當對辦案過程中知悉的國家秘密、商業秘密和個人隱私予以保密。"},
  "辦理《香港國安法》案件的執法司法人員，應否公開知悉的國家秘密和個人隱私？": {"law":"《識法導航》","ref":"《識法導航》中學版 第六程 · Q133（第17頁） · 第六章 附則 · 第六十三條","text":"辦理本法規定的危害國家安全犯罪案件的有關執法、司法機關及其人員……應當對辦案過程中知悉的國家秘密、商業秘密和個人隱私予以保密。"},
  "香港本地法律與《港區國安法》不一致時，適用哪一項？": {"law":"學習參考資料","ref":"第六章 附則 · 第六十二條","text":"香港特別行政區本地法律規定與本法不一致的,適用本法規定。"},
  "《中華人民共和國出口管制法》於何時通過？": {"law":"《出口管制法》","ref":"《出口管制法》 · 公布令","text":"《中華人民共和國出口管制法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十二次會議於2020年10月17日通過,現予公布,自2020年12月1日起施行。"},
  "《出口管制法》自何時起施行？": {"law":"《出口管制法》","ref":"《出口管制法》 · 公布令","text":"《中華人民共和國出口管制法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十二次會議於2020年10月17日通過,現予公布,自2020年12月1日起施行。"},
  "《出口管制法》的立法目的是維護國家安全和利益，並履行甚麼等國際義務？": {"law":"《出口管制法》","ref":"《出口管制法》 · 第一條","text":"為了維護國家安全和利益,履行防擴散等國際義務,加強和規範出口管制,制定本法。"},
  "《中華人民共和國生物安全法》於何時通過？": {"law":"《生物安全法》","ref":"《生物安全法》 · 公布令","text":"《中華人民共和國生物安全法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十二次會議於2020年10月17日通過,現予公布,自2021年4月15日起施行。"},
  "《生物安全法》自何時起施行？這一天同時是甚麼日子？": {"law":"《生物安全法》","ref":"《生物安全法》 · 公布令；《國家安全法》第十四條","text":"《中華人民共和國生物安全法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十二次會議於2020年10月17日通過,現予公布,自2021年4月15日起施行。每年4月15日為全民國家安全教育日。"},
  "《生物安全法》的立法目的是防範和應對甚麼風險？": {"law":"《生物安全法》","ref":"《生物安全法》 · 第一條","text":"為了維護國家安全,防範和應對生物安全風險,保障人民生命健康,保護生物資源和生態環境,促進生物技術健康發展,推動構建人類命運共同體,實現人與自然和諧共生,制定本法。"},
  "《中華人民共和國國防法》修訂後自何時起施行？": {"law":"《國防法》","ref":"《國防法》（2020年修訂） · 公布令","text":"《中華人民共和國國防法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十四次會議於2020年12月26日修訂通過,現將修訂後的《中華人民共和國國防法》公布,自2021年1月1日起施行。"},
  "《中華人民共和國海警法》於何時通過？": {"law":"《海警法》","ref":"《海警法》 · 公布令","text":"《中華人民共和國海警法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十五次會議於2021年1月22日通過,現予公布,自2021年2月1日起施行。"},
  "根據《海警法》，統一履行海上維權執法職責的是甚麼機構？": {"law":"《海警法》","ref":"《海警法》 · 第二條","text":"人民武裝警察部隊海警部隊即海警機構,統一履行海上維權執法職責。"},
  "《中華人民共和國反外國制裁法》於何時通過並施行？": {"law":"《反外國制裁法》","ref":"《反外國制裁法》 · 公布令","text":"《中華人民共和國反外國制裁法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十九次會議於2021年6月10日通過,現予公布,自公布之日起施行。"},
  "《反外國制裁法》的立法目的是維護國家主權、安全、發展利益，並保護誰的合法權益？": {"law":"《反外國制裁法》","ref":"《反外國制裁法》 · 第一條","text":"為了維護國家主權、安全、發展利益,保護我國公民、組織的合法權益,根據憲法,制定本法。"},
  "《中華人民共和國數據安全法》於何時通過？": {"law":"《數據安全法》","ref":"《數據安全法》 · 公布令","text":"《中華人民共和國數據安全法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十九次會議於2021年6月10日通過,現予公布,自2021年9月1日起施行。"},
  "《數據安全法》自何時起施行？": {"law":"《數據安全法》","ref":"《數據安全法》 · 公布令","text":"《中華人民共和國數據安全法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第二十九次會議於2021年6月10日通過,現予公布,自2021年9月1日起施行。"},
  "根據《數據安全法》，國家數據安全工作的決策和議事協調由哪個機構負責？": {"law":"《數據安全法》","ref":"《數據安全法》 · 第五條","text":"中央國家安全領導機構負責國家數據安全工作的決策和議事協調,研究制定、指導實施國家數據安全戰略和有關重大方針政策,統籌協調國家數據安全的重大事項和重要工作,建立國家數據安全工作協調機制。"},
  "《中華人民共和國個人信息保護法》於何時通過？": {"law":"《個人信息保護法》","ref":"《個人信息保護法》 · 公布令","text":"《中華人民共和國個人信息保護法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十次會議於2021年8月20日通過,現予公布,自2021年11月1日起施行。"},
  "《個人信息保護法》自何時起施行？": {"law":"《個人信息保護法》","ref":"《個人信息保護法》 · 公布令","text":"《中華人民共和國個人信息保護法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十次會議於2021年8月20日通過,現予公布,自2021年11月1日起施行。"},
  "根據《個人信息保護法》，負責統籌協調個人信息保護工作的部門是？": {"law":"《個人信息保護法》","ref":"《個人信息保護法》 · 第六十條","text":"國家網信部門負責統籌協調個人信息保護工作和相關監督管理工作。"},
  "《中華人民共和國陸地國界法》於何時通過？": {"law":"《陸地國界法》","ref":"《陸地國界法》 · 公布令","text":"《中華人民共和國陸地國界法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十一次會議於2021年10月23日通過,現予公布,自2022年1月1日起施行。"},
  "《陸地國界法》自何時起施行？": {"law":"《陸地國界法》","ref":"《陸地國界法》 · 公布令","text":"《中華人民共和國陸地國界法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十一次會議於2021年10月23日通過,現予公布,自2022年1月1日起施行。"},
  "《中華人民共和國反有組織犯罪法》於何時通過？": {"law":"《反有組織犯罪法》","ref":"《反有組織犯罪法》 · 公布令","text":"《中華人民共和國反有組織犯罪法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十二次會議於2021年12月24日通過,現予公布,自2022年5月1日起施行。"},
  "《反有組織犯罪法》自何時起施行？": {"law":"《反有組織犯罪法》","ref":"《反有組織犯罪法》 · 公布令","text":"《中華人民共和國反有組織犯罪法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十二次會議於2021年12月24日通過,現予公布,自2022年5月1日起施行。"},
  "《中華人民共和國反電信網絡詐騙法》於何時通過？": {"law":"《反電信網絡詐騙法》","ref":"《反電信網絡詐騙法》 · 公布令","text":"《中華人民共和國反電信網絡詐騙法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十六次會議於2022年9月2日通過,現予公布,自2022年12月1日起施行。"},
  "《反電信網絡詐騙法》自何時起施行？": {"law":"《反電信網絡詐騙法》","ref":"《反電信網絡詐騙法》 · 公布令","text":"《中華人民共和國反電信網絡詐騙法》已由中華人民共和國第十三屆全國人民代表大會常務委員會第三十六次會議於2022年9月2日通過,現予公布,自2022年12月1日起施行。"},
  "《反電信網絡詐騙法》訂明哪個機關牽頭負責反電信網絡詐騙工作？": {"law":"《反電信網絡詐騙法》","ref":"《反電信網絡詐騙法》 · 第六條","text":"公安機關牽頭負責反電信網絡詐騙工作,金融、電信、網信、市場監管等有關部門依照職責履行監管主體責任。"},
  "《中華人民共和國反間諜法》最近一次修訂於何時通過？": {"law":"《反間諜法》","ref":"《反間諜法》（2023年修訂） · 公布令","text":"《中華人民共和國反間諜法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第二次會議於2023年4月26日修訂通過,現將修訂後的《中華人民共和國反間諜法》公布,自2023年7月1日起施行。"},
  "修訂後的《反間諜法》自何時起施行？": {"law":"《反間諜法》","ref":"《反間諜法》（2023年修訂） · 公布令","text":"《中華人民共和國反間諜法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第二次會議於2023年4月26日修訂通過,現將修訂後的《中華人民共和國反間諜法》公布,自2023年7月1日起施行。"},
  "《反間諜法》訂明反間諜工作的主管機關是？": {"law":"《反間諜法》","ref":"《反間諜法》（2023年修訂） · 第六條","text":"國家安全機關是反間諜工作的主管機關。"},
  "《中華人民共和國對外關係法》於何時通過？": {"law":"《對外關係法》","ref":"《對外關係法》 · 公布令","text":"《中華人民共和國對外關係法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第三次會議於2023年6月28日通過,現予公布,自2023年7月1日起施行。"},
  "《對外關係法》訂明推動構建甚麼？": {"law":"《對外關係法》","ref":"《對外關係法》 · 第一條","text":"為了發展對外關係,維護國家主權、安全、發展利益,維護和發展人民利益,建設社會主義現代化強國,實現中華民族偉大復興,促進世界和平與發展,推動構建人類命運共同體,根據憲法,制定本法。"},
  "《中華人民共和國愛國主義教育法》於何時通過？": {"law":"《愛國主義教育法》","ref":"《愛國主義教育法》 · 公布令","text":"《中華人民共和國愛國主義教育法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第六次會議於2023年10月24日通過,現予公布,自2024年1月1日起施行。"},
  "《愛國主義教育法》自何時起施行？": {"law":"《愛國主義教育法》","ref":"《愛國主義教育法》 · 公布令","text":"《中華人民共和國愛國主義教育法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第六次會議於2023年10月24日通過,現予公布,自2024年1月1日起施行。"},
  "《愛國主義教育法》的立法目的是加強新時代甚麼，傳承和弘揚甚麼？": {"law":"《愛國主義教育法》","ref":"《愛國主義教育法》 · 第一條","text":"為了加強新時代愛國主義教育,傳承和弘揚愛國主義精神,凝聚全面建設社會主義現代化國家、全面推進中華民族偉大復興的磅礴力量,根據憲法,制定本法。"},
  "《中華人民共和國糧食安全保障法》於何時通過？": {"law":"《糧食安全保障法》","ref":"《糧食安全保障法》 · 公布令","text":"《中華人民共和國糧食安全保障法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第七次會議於2023年12月29日通過,現予公布,自2024年6月1日起施行。"},
  "《糧食安全保障法》自何時起施行？": {"law":"《糧食安全保障法》","ref":"《糧食安全保障法》 · 公布令","text":"《中華人民共和國糧食安全保障法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第七次會議於2023年12月29日通過,現予公布,自2024年6月1日起施行。"},
  "《糧食安全保障法》訂明提高防範和抵禦甚麼風險的能力？": {"law":"《糧食安全保障法》","ref":"《糧食安全保障法》 · 第一條","text":"為了保障糧食有效供給,確保國家糧食安全,提高防範和抵禦糧食安全風險能力,維護經濟社會穩定和國家安全,根據憲法,制定本法。"},
  "《中華人民共和國保守國家秘密法》修訂後自何時起施行？": {"law":"《保守國家秘密法》","ref":"《保守國家秘密法》（2024年修訂） · 公布令","text":"《中華人民共和國保守國家秘密法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第八次會議於2024年2月27日修訂通過,自2024年5月1日起施行。"},
  "《中華人民共和國突發事件應對法》修訂後自何時起施行？": {"law":"《突發事件應對法》","ref":"《突發事件應對法》（2024年修訂） · 公布令","text":"《中華人民共和國突發事件應對法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第十次會議於2024年6月28日修訂通過,自2024年11月1日起施行。"},
  "《中華人民共和國國防教育法》修訂後自何時起施行？": {"law":"《國防教育法》","ref":"《國防教育法》（2024年修訂） · 公布令","text":"《中華人民共和國國防教育法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第十一次會議於2024年9月13日修訂通過,自2024年9月21日起施行。"},
  "《中華人民共和國反洗錢法》修訂後自何時起施行？": {"law":"《反洗錢法》","ref":"《反洗錢法》（2024年修訂） · 公布令","text":"《中華人民共和國反洗錢法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第十二次會議於2024年11月8日修訂通過,自2025年1月1日起施行。"},
  "香港《維護國家安全條例》於何日在立法會三讀通過？": {"law":"學習參考資料","ref":"香港特區政府新聞公報 · 2024年3月19日","text":"立法會於2024年3月19日三讀全票通過《維護國家安全條例》,履行《基本法》第二十三條和《香港國安法》第七條的憲制責任。"},
  "香港《維護國家安全條例》自何日起刊憲生效？": {"law":"學習參考資料","ref":"香港特區政府新聞公報 · 2024年3月23日","text":"《維護國家安全條例》於2024年3月23日刊憲生效。"},
  "香港《維護國家安全條例》是為履行《香港國安法》哪一條的規定？": {"law":"《香港國安法》","ref":"《香港國安法》（文件 A302） · 第七條","text":"香港特別行政區應當儘早完成香港特別行政區基本法規定的維護國家安全立法,完善相關法律。"},
  "《中華人民共和國治安管理處罰法》修訂後自何時起施行？": {"law":"《治安管理處罰法》","ref":"《治安管理處罰法》（2025年修訂） · 公布令","text":"《中華人民共和國治安管理處罰法》已由中華人民共和國第十四屆全國人民代表大會常務委員會第十六次會議於2025年6月27日修訂通過,自2026年1月1日起施行。"},
  "《中華人民共和國網絡安全法》修正後自何時起施行？": {"law":"《網絡安全法》","ref":"《網絡安全法》（2025年修正） · 修改決定","text":"第十四屆全國人民代表大會常務委員會第十八次會議於2025年10月28日表決通過《全國人民代表大會常務委員會關於修改〈中華人民共和國網絡安全法〉的決定》,自2026年1月1日起施行。"},
  "《中華人民共和國國家安全法》共設置了多少章多少條？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 國家安全的含意","text":"法例共設置了「總則」、「維護國家安全的任務」、「維護國家安全的職責」、「國家安全制度」、「國家安全保障」、「公民、組織的義務和權利」及「附則」共7章84條。"},
  "《中華人民共和國國家安全法》於何時通過？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 國家安全的含意","text":"2015年7月1日，第十二屆全國人大常委會第十五次會議表決通過了《中華人民共和國國家安全法》。"},
  "《香港國安法》會不會影響香港居民的遊行、示威、新聞、言論等基本權利和自由？": {"law":"參考資料","ref":"《識法導航》中學版 第六程 · Q141（第18頁）","text":"《香港國安法》不影響香港居民依法享有的遊行、示威、新聞、言論等權利和自由。"},
  "「五大要素」以什麼為依托？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"（五）以促進國際安全為依托。"},
  "「以人民安全為宗旨」就是要堅持什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"就是要堅持以民為本﹑以人為本。堅持國家安全一切為了人民的福祉，依靠人民，穩固國家安全的群衆基礎，讓人民休養生息，安居樂業。"},
  "「以促進國際安全為依托」要求始終不渝走什麼道路？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"就是要始終不渝走和平發展道路，在注重維護本土國家安全利益的同時，注重維護共同安全。"},
  "「以政治安全為根本」是把什麼安全放在首位？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"就是堅決維護國家主權不容侵犯以及中華人民共和國的根本制度和最本質的特徵，把制度和政權安全放在首位，為國家安全提供根本政治保證。"},
  "「以經濟安全為基礎」是要確保什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"就是要確保經濟發展不受侵害，促進經濟持續健康發展，增強國家經濟實力，為國家安全提供堅實物質基礎。"},
  "「十個堅持」包括哪些？": {"law":"學習參考資料","ref":"nsed.gov.hk · 總體國家安全觀十個堅持（圖表 OCR）","text":"堅持黨對國家安全工作的絕對領導、中國特色國家安全道路、以人民安全為宗旨、統籌發展和安全、把政治安全放在首要位置、統籌推進各領域安全、把防範化解國家安全風險擺在突出位置、推進國際共同安全、推進國家安全體系和能力現代化、加強國家安全幹部隊伍建設。"},
  "「十個堅持」首要堅持什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 總體國家安全觀十個堅持（圖表 OCR）","text":"（一）堅持黨對國家安全工作的絕對領導。"},
  "「四大着力點」出自哪一年什麼會議的報告？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀四大着力點","text":"2022年，中國共產黨第二十次全國代表大會的報告對推進國家安全體系和能力現代化作出了戰略部署，明確指出四項任務。"},
  "「四大着力點」體現了什麼新要求？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀四大着力點","text":"體現了「以新安全格局保障新發展格局」的新要求，強調推動國家安全體系和能力現代化，要從「四大着力點」加快構建新安全格局。"},
  "「統籌外部安全和內部安全」要求對內、對外分別求什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五個統籌","text":"總體國家安全觀明確要求對內求發展、求變革、求穩定、建設平安中國，對外求和平、求合作、求共贏、建設和諧世界。"},
  "什麼是更高層次、更具前瞻性的維護國家安全？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五個統籌","text":"塑造國家安全是更高層次、更具前瞻性的維護國家安全。"},
  "全面貫徹落實總體國家安全觀才能確保什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"全面貫徹落實總體國家安全觀才能確保國家安全、人民安全，其核心要義可歸納為「一個總體」、「五大要素」、「五個統籌」。"},
  "哪一個統籌進一步證實國民安全、人民安全是總體國家安全觀的第一要義與核心價值？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五個統籌","text":"堅持以民為本、以人為本，堅持國家安全一切為了人民、一切依靠人民，真正夯實國家安全的群衆基礎，進一步證實了國民安全、人民安全是總體國家安全觀的第一要義與核心價值。"},
  "國家安全是什麼的重要基石？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 國家安全的含意","text":"國家安全關乎包括香港同胞在內的全中國14億人民的福祉，是安邦定國的重要基石。當國家的核心利益遇到危險，國家安全便受到威脅，人民安全亦無從談起。"},
  "國家安全的16個範疇包括哪些領域？": {"law":"參考資料","ref":"《識法導航》中學版 第六程 · Q138（第18頁）","text":"16個範疇：政治、國土、軍事、經濟、文化、社會、科技、網絡、生態、資源、核、海外利益、生物、太空、深海、極地安全。"},
  "國家安全的重點領域中，傳統安全包括哪些？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"傳統安全：政治安全、軍事安全、國土安全。"},
  "國家安全的重點領域中，非傳統安全包括哪些？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"非傳統安全：經濟安全、金融安全、文化安全、社會安全、科技安全、網絡安全、糧食安全、生態安全、資源安全、核安全、海外利益安全、太空安全、深海安全、極地安全、生物安全、人工智能安全、數據安全。"},
  "國家安全除了重視外部安全，還重視甚麼安全？": {"law":"參考資料","ref":"《識法導航》中學版 第六程 · Q140（第18頁）","text":"總體國家安全觀重視外部安全，也重視內部安全，兩者並重。"},
  "推進國家安全體系和能力現代化，要堅持什麼、強化什麼思維？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五個統籌","text":"推進國家安全體系和能力現代化，要堅持科學統籌，強化系統思維、辯證思維，全面把握、整體謀劃、協調推進。"},
  "根據《國家安全法》第二條，國家安全是指什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 國家安全的含意","text":"《中華人民共和國國家安全法》第二條：國家安全是指國家政權、主權、統一和領土完整、人民福祉、經濟社會可持續發展和國家其他重大利益相對處於沒有危險和不受內外威脅的狀態，以及保障持續安全狀態的能力。"},
  "生態安全包括甚麼範疇？": {"law":"參考資料","ref":"《識法導航》中學版 第六程 · Q139（第18頁）","text":"生態安全包括水資源安全、土地資源安全、大氣資源安全、生物物種安全。"},
  "總體國家安全觀強調以什麼角度理解和維護國家安全，突出的是什麼概念？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"總體國家安全觀強調要以整體角度，全盤理解和維護國家的整體安全，突出的是「大安全」概念，涵蓋二十個環環相扣的重點領域。"},
  "總體國家安全觀涵蓋多少個環環相扣的重點領域？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"總體國家安全觀強調要以整體角度，全盤理解和維護國家的整體安全，突出的是「大安全」概念，涵蓋二十個環環相扣的重點領域。"},
  "總體國家安全觀由誰於何時提出？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"總體國家安全觀由習近平總書記於2014年4月15日創造性提出，是一個系統完整、邏輯嚴密、互相貫通的完整科學理論體系，是有效應對新時代國家安全形勢重大變化所帶來的各種風險和挑戰的根本遵循與行動指南。"},
  "總體國家安全觀的「五個統籌」是什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五個統籌","text":"（一）統籌外部安全和內部安全（二）統籌國土安全和國民安全（三）統籌傳統安全和非傳統安全（四）統籌自身安全和共同安全（五）統籌維護和塑造國家安全"},
  "總體國家安全觀的「五大要素」是什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀五大要素","text":"（一）以人民安全為宗旨（二）以政治安全為根本（三）以經濟安全為基礎（四）以軍事、科技、文化、社會安全為保障（五）以促進國際安全為依托"},
  "總體國家安全觀的「四大着力點」是什麼？": {"law":"學習參考資料","ref":"nsed.gov.hk · 總體國家安全觀四大着力點（圖表 OCR）","text":"健全國家安全體系、增強維護國家安全能力、提高公共安全治理水平、完善社會治理體系。"},
  "總體國家安全觀的核心要義可歸納為哪三項？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀","text":"其核心要義可歸納為「一個總體」、「五大要素」、「五個統籌」。"},
  "習近平總書記在什麼場合提出貫徹總體國家安全觀的「十個堅持」要求？": {"law":"學習參考資料","ref":"nsed.gov.hk · 認識國家安全 · 總體國家安全觀十個堅持","text":"2020年12月11日，習近平總書記在中共中央政治局第二十六次集體學習中，就貫徹總體國家安全觀提出「十個堅持」要求。"},
  "2020年，新冠肺炎疫情爆發跟國家安全的哪一個領域有直接關係？": {"law":"參考資料","ref":"《識法導航》中學版 第六程 · Q143（第19頁）","text":"2020年新冠肺炎疫情與國家安全的生物安全領域直接相關。"},
  "中國努力爭取於哪一年前實現碳中和？": {"law":"國家承諾","ref":"《識法導航》中學版 第六程 · Q142（第18頁）","text":"中國力爭2060年前實現碳中和（2030年前碳達峰）。"},
  "北部都會區共建哪三個大學城？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第9頁 · 特刊第9頁","text":"北部都會區共建新田、洪水橋、打鼓嶺三個大學城。"},
  "北部都會區大學城以「一城五元素」作布局，包括哪五個元素？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第9頁 · 特刊第9頁","text":"「一城五元素」：教育、科技、產業、人才和城市建設。"},
  "北部都會區發展將訂立什麼條例？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第9頁 · 特刊第9頁","text":"北部都會區發展將訂立《北部都會區發展條例》及其附屬法例。"},
  "台灣是否獨立的國家？": {"law":"官方立場","ref":"《識法導航》中學版 第六程 · Q145（第19頁）","text":"台灣是中國的一部分，不是獨立的國家。"},
  "河套深港科技創新合作區以什麼願景開發建設？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第9頁 · 特刊第9頁","text":"河套深港科技創新合作區以「一河兩岸、一區兩園」願景開發建設。"},
  "粵港澳大灣區在國家發展格局中的定位是什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第8頁 · 特刊第8頁","text":"大灣區定位：國家新發展格局的戰略支點、高質量發展的示範地、中國式現代化的引領地。"},
  "習近平在《告台灣同胞書》發表40週年紀念會上，就甚麼問題發表重要講話？": {"law":"事實","ref":"《識法導航》中學版 第六程 · Q144（第19頁）","text":"習近平在《告台灣同胞書》發表40週年紀念會上，就推動和平統一發表重要講話。"},
  "行政長官每年向誰述職並報告五年規劃實施情況？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第13頁 · 特刊第13頁","text":"行政長官每年向國家主席和中央政府述職並報告五年規劃實施情況。"},
  "香港五年規劃中，維護國家安全以什麼為指引？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第12頁","text":"以總體國家安全觀為指引，持續完善特區維護國家安全的頂層設計、法律制度和執行機制。"},
  "香港五年規劃共訂定了多少個指標？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第14頁","text":"The First Five-Year Plan sets out a total of 105 indicators, including 22 major indicators in Part 1, 57 work indicators set out in the respective tables, and 26 work indicators contained in the main text of individual chapters."},
  "香港五年規劃提出堅持什麼、強化什麼，以維護國家安全？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第12頁 · 特刊第12頁","text":"堅持有法必依、執法必嚴、違法必究，並強化國家安全教育。"},
  "香港五年規劃是在國家哪個規劃的開局之年制定的？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第3頁 · 特刊第3頁","text":"香港五年規劃在國家「十五五」規劃的開局之年制定。"},
  "香港五年規劃的「四中心、一高地」指什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第5-6頁 · 特刊第5-6頁","text":"「四中心、一高地」：國際金融中心、國際航運中心和航空樞紐、國際貿易中心、國際創新科技中心、國際高端人才集聚高地。"},
  "香港五年規劃的七個理念是什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第3頁","text":"堅持「一國兩制」方針、民生為本、行政主導、改革創新、「有效市場」和「有為政府」相結合、統籌發展和安全、規劃務實有為。"},
  "香港五年規劃的五個主要目標是什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第3頁 · 特刊第3頁","text":"五個主要目標：經濟發展取得新突破、國際競爭力和影響力持續提升、北部都會區建設加速提效、民生福祉顯著改善、融入和服務國家發展大局取得重大進展。"},
  "香港全速構建的「三大創科園區」指什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第6頁 · 特刊第6頁","text":"三大創科園區：河套深港科技創新合作區香港園區和新田科技城、科學園、數碼港。"},
  "香港建立了什麼機制落實五年規劃？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第13頁 · 特刊第13頁","text":"「五年規劃統領、年度施政落實、財政預算支持、年度述職滙報」機制。"},
  "香港推進建設的「五大研發機構」是什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第6頁 · 特刊第6頁","text":"五大研發機構：香港生產力促進局、香港應用科技研究院、香港微電子研發院、香港人工智能研發院及生命健康研發院。"},
  "香港特別行政區首份五年規劃的全名是什麼？": {"law":"《香港五年規劃》","ref":"《香港五年規劃》特刊（highlights_full.pdf） · 第3頁 · 特刊第3頁","text":"全名為《香港特別行政區經濟和社會發展第一個五年規劃（2026-2030年）》。"},
};
